(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-disagg-prefill-decode-rollout"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-1\">一 · 事故现场：一次 rollout 批次卡在 3% 不收敛</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-2\">二 · 它解决什么：把两个阶段的资源曲线解耦</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-3\">三 · 它不解决什么：三条明确的排除线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-4\">四 · 规模上限与工程复杂度：路由、句柄、故障转移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-5\">五 · 适用判断：从负载配方反推是否拆分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-6\">六 · 当长 prompt 撞上短生成：一次 rollout 批次悬挂暴露的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-7\">七 · 调度器入口：请求分类与路由决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-8\">八 · Prefill 实例：chunked prefill 与 KV 产出</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-9\">九 · KV 跨池传输：带宽账与原子注册</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-10\">十 · Decode 实例接管：continuous batching 与增量 KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-11\">十一 · 回传与释放：logprob 回流与块回收</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-12\">十二 · 两池独立伸缩：按不同指标扩容</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-13\">十三 · 拆分收益的边界：KV 搬运与两池一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-14\">十四 · Goodput 公式的分母：两池木桶效应的数学形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-15\">十五 · 端到端时延分解与 KV 传输项的推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-16\">十六 · 路由与准入的伪代码：把公式变成判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-17\">十七 · 两池扩缩容的速率匹配推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-18\">十八 · 权重同步窗口与两池版本一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-19\">十九 · 拆分的失效边界：传输项如何吃掉收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-20\">二十 · 请求形态决定拆分是否有意义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-21\">二十一 · 批大小必须按池分别组织</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-22\">二十二 · 负载配方错配时的三种劣化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-23\">二十三 · 路由与准入：配方在调度器里的落地</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-24\">二十四 · 配方与并行策略的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-25\">二十五 · 配方判断的工程准则</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-26\">二十六 · 负载配方与失效边界：什么时候拆池是赚的，什么时候是赔的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-27\">二十七 · 硬件档位：按池的瓶颈选卡，而不是按整机选卡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-28\">二十八 · 并行拓扑：prefill偏TP，decode偏EP/DP，拓扑随池走</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-29\">二十九 · 量化方案：两池分别定精度，KV传输格式单独定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-30\">三十 · KV策略：块粒度、传输原子性、容量回收三件事</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-31\">三十一 · 调度参数：两池各自的队列阈值与伸缩触发条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-32\">三十二 · 可复现的配置思路：从SLO反推，按池定档，用公式验收</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-33\">三十三 · 拆池配方的失效边界：互联带宽预算与两池版本一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-34\">三十四 · 互联带宽：KV 跨池传输的物理上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-35\">三十五 · 显存与块表：decode 池的容量墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-36\">三十六 · 功耗与并行策略的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-37\">三十七 · 尾延迟：木桶效应的真实形状</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-38\">三十八 · 规模上去以后哪里先崩：故障转移与版本一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-39\">三十九 · 互联带宽与尾延迟：拆分方案先崩在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-40\">四十 · 精度漂移：两池版本不一致与数值路径分叉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-41\">四十一 · OOM 的三条来路与块表对账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-42\">四十二 · 批抖动与路由不均：队列深度是唯一可信信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-43\">四十三 · 尾延迟尖刺：KV 传输与块表注册的原子性缺口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-44\">四十四 · 监控面与回滚：把两池当一条链路来观测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-45\">四十五 · 跨池边界的失效面：从 KV 句柄悬挂到版本漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-46\">四十六 · 对照轴：拆分粒度与争抢消除方式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-47\">四十七 · 决策表：五类负载的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-48\">四十八 · 与投机、量化、批不变条目的组合关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-49\">四十九 · 与异步Rollout流水线的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-50\">五十 · 适用条件的量化门槛与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-51\">五十一 · 拆与不拆之间：同族算法怎么选，以及本方案的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-prefill-decode-rollout-sec-52\">五十二 · 同族算法怎么选：拆分收益的边界与失效条件</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:499px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 499.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"417.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">rollout调度器接收采样请求，按prompt长度路由到prefill池…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"417.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">prefill实例将KV块通过高速互联（NVLink或RDMA）传输到de…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"417.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">decode实例接管请求，以continuous batching推进自回…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"417.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">生成结束的请求把token序列与logprob回传rollout调度器，d…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"417.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">两池按队列深度与SLO分别做副本伸缩，prefill池按prompt to…</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-1\">一 · 事故现场：一次 rollout 批次卡在 3% 不收敛</h3>\n<p>某 RL 训练任务在 B200 单机上跑 GRPO 的 rollout 阶段，采样请求来自同一批数学题与代码题混合的 prompt 集。数学题的 prompt 只有几十个 token，但 CoT 生成能拉到数千 token；代码题的 prompt 塞满整段仓库上下文，动辄数万 token，而补全只有几百 token。引擎按请求到达顺序把它们塞进同一个 continuous batching 批次，prefill 与 decode 共享同一组 SM 与 HBM 带宽。结果是：长 prompt 的 chunked prefill 一进来就把 decode 步骤的 TPOT 顶上去，正在生成的 CoT 序列被迫拉长间隔；而 decode 侧持续占用 SM 又让新到的长 prompt 排队，TTFT 冲高。调度器为了压 TPOT 把批大小调小，prefill 吞吐随之下降，队列更深，形成正反馈。</p>\n<p>更糟的是故障形态：一个长 prompt 的 KV 块在 prefill 实例上产出后，块表注册与传输句柄的绑定在并发路径上出现不一致，请求被标记为“已派发”但 decode 实例从未收到 KV。该请求既不超时也不报错，rollout 调度器一直等它的 logprob 回传，整个批次因为缺少这几条样本而无法凑齐 advantage 计算所需的组，训练侧空转。这就是本算法要解决的具体问题：不是“推理慢”，而是<strong>prefill 与 decode 在同一执行资源上互相抢占，导致 TTFT 与 TPOT 无法同时达标，且跨阶段状态交接缺乏原子性时批次会悬挂</strong>。</p>\n<div class=\"formula\">$$\\text{Goodput} = \\max\\ \\frac{N_{\\text{req}}}{\\max\\left(\\frac{\\sum L_p}{\\text{thr}_{\\text{prefill}}},\\ \\frac{\\sum L_o}{\\text{thr}_{\\text{decode}}}\\right)},\\quad \\text{s.t.}\\ \\text{TTFT}\\le S_{\\text{TTFT}},\\ \\text{TPOT}\\le S_{\\text{TPOT}}$$</div>\n<p>这个式子点明了木桶效应的来源：分子是请求数，分母取 prefill 总时长与 decode 总时长中的较大者。当两类请求的长度分布高度异质时，同一张卡上两个阶段的资源配比无法同时匹配两条曲线——prefill 偏好的大 chunk、高 SM 占用与 decode 偏好的小步进、低干扰天然冲突。事故里的“调小批大小压 TPOT”正是在分母上做文章，代价是把 prefill 那一项推得更高，Goodput 反而下降。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-2\">二 · 它解决什么：把两个阶段的资源曲线解耦</h3>\n<p>算法的核心动作是把 rollout 引擎拆成 prefill 池与 decode 池。prefill 池只做 prompt 的 chunked prefill，产出完整 prompt KV；decode 池只做自回归生成，每步只写新 token 的 KV。两池按各自最优并行度独立扩缩容：prefill 偏 TP（长 prompt 的矩阵乘需要跨卡切分以压低单请求时延），decode 偏 EP/DP（大量并发短步进更看重序列级并行与显存容量）。这样同卡抢占被物理消除，TTFT 由 prefill 池的 chunk 调度与队列深度决定，TPOT 由 decode 池的 continuous batching 并发序列数决定，两个 SLO 可以分别调参而不是互相拉扯。</p>\n<p>数据流按顺序是：rollout 调度器接收采样请求，按 prompt 长度路由到 prefill 池的某个实例；prefill 实例做 chunked prefill 产出完整 prompt KV；随后把 KV 块经 NVLink 或 RDMA 传到 decode 池目标实例的 HBM，<strong>传输与块表注册原子完成</strong>——这一步正是事故里缺失的语义，原子性保证“decode 侧可见的 KV 句柄”与“已落地的 KV 数据”永远一致，不会出现派发成功但数据未到的悬挂态。decode 实例接管后以 continuous batching 推进生成，结束时把 token 序列与 logprob 回传调度器并释放 KV 块。两池分别按队列深度伸缩：prefill 池按 prompt token/s 扩容，decode 池按并发序列数扩容。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>同卡混跑（事故形态）</th><th>分离式两池</th></tr></thead><tbody><tr><td>TTFT 决定因素</td><td>decode 占用 SM 的剩余量</td><td>prefill 池 chunk 调度与队列深度</td></tr><tr><td>TPOT 决定因素</td><td>prefill 大 chunk 的干扰</td><td>decode 池并发序列数与显存带宽</td></tr><tr><td>扩容粒度</td><td>整机重配，比例固定</td><td>按池独立伸缩，比例随负载漂移</td></tr><tr><td>失败形态</td><td>批次因个别请求悬挂不收敛</td><td>传输/注册原子性可定位、可重试</td></tr></tbody></table>\n<p>代价必须说清楚：KV 跨池传输引入额外互联带宽开销。长 prompt 下 KV 体积可达数百 MB，传输时延可能吃掉 prefill 节省的时间，端到端时延近似为</p>\n<div class=\"formula\">$$T_{\\text{e2e}}=T_{\\text{prefill}}+T_{\\text{kv\\_transfer}}+T_{\\text{decode}}$$</div>\n<p>也就是说，拆分不是免费的午餐：只有当 $T_{\\text{kv\\_transfer}}$ 相对于被消除的抢占损失足够小，净收益才成立。这就是适用边界的第一条硬约束——互联带宽。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-3\">三 · 它不解决什么：三条明确的排除线</h3>\n<p>第一，它不解决同一 prompt 多采样之间的 KV 重复计算。若一个数学题要采 16 条 CoT，前缀 KV 在每条采样里被重复 prefill，这是前缀共享要处理的问题，分离式两池只是把这 16 次 prefill 挪到 prefill 池里做，重复量不变。第二，它不解决分块预填与解码在同一实例内的交错搭载——那是另一条路径的优化目标，本算法选择的是物理拆分而非时间片交错。第三，它不解决量化精度与数值稳定性：NVFP4/FP8 下的 KV 缩放因子、tcgen05 路径的累加精度问题在两池里同样存在，拆分只是改变了它们发生的物理位置。</p>\n<p>还有一条容易被误读的边界：短 prompt 短生成的场景下，拆分收益不足以抵消传输开销。此时 $T_{\\text{prefill}}$ 与 $T_{\\text{decode}}$ 都很小，$T_{\\text{kv\\_transfer}}$ 在端到端时延中的占比被放大，两池的路由与句柄维护成本却照付。判断标准应落在“长度分布异质度”上：当 prompt 长度与生成长度的联合分布足够分散，木桶效应造成的 Goodput 损失超过传输开销时，拆分才划算。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-4\">四 · 规模上限与工程复杂度：路由、句柄、故障转移</h3>\n<p>规模上限受互联带宽与两池路由/故障转移复杂度双重约束。KV 体积随 prompt 长度线性增长，数百 MB 量级的单请求 KV 在 NVLink 域内尚可接受，一旦跨节点走 RDMA，带宽与尾时延就成为瓶颈；decode 池的并发序列数越多，需要同时驻留的 KV 块越多，HBM 容量与块表管理的压力也越大。两池之间要维护请求路由表、KV 句柄生命周期、以及传输失败时的故障转移——事故里那种“派发成功但数据未到”的悬挂，在拆分后必须以原子注册加显式超时重试来兜底，否则 rollout 批次同样无法收敛。</p>\n<p>另一个隐性代价在权重同步：rollout 引擎与训练侧的权重更新需同时覆盖 prefill 池与 decode 池。同步窗口内若两池版本不一致，prefill 用旧权重算出的 KV 与 decode 用新权重生成的 token 会混在同一请求里，采样分布出现偏差，而这种偏差在 RL 里会直接污染 advantage 估计。工程上要么做两池同步切换的屏障，要么在路由层按版本号隔离请求，两者都增加调度复杂度。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-5\">五 · 适用判断：从负载配方反推是否拆分</h3>\n<p>给出一个可操作的判断路径。先统计 rollout 请求的 prompt 长度与生成长度联合分布：若两类请求的 $L_p$ 与 $L_o$ 呈明显负相关（短 prompt 长 CoT、长 prompt 短补全），同卡混跑的抢占损失最大，拆分收益最高；若分布集中且长度接近，木桶效应本就弱，拆分不划算。再看 SLO 形态：TTFT 与 TPOT 需同时达标而非单一吞吐指标时，两池独立调参的价值才显现；若只关心总吞吐、对首 token 时延不敏感，同卡混跑的大批次反而更省互联。</p>\n<p>最后看互联档位：NVLink 域内的 KV 传输时延可控，拆分门槛低；跨节点 RDMA 则要先估算单请求 KV 体积与链路带宽的比值，数百 MB 的 KV 在有限带宽下传输时延会直接吃掉 prefill 节省的时间，此时应优先压缩 KV（量化、分页）或缩短 prompt，而不是贸然拆池。事故复盘给出的工程判断是：分离式预填解码的第一性问题是<strong>把 TTFT 与 TPOT 的资源曲线解耦，同时用原子化的 KV 交接保证批次可收敛</strong>；它的成立条件是长度分布足够异质、互联带宽足以覆盖 KV 传输、且两池的路由与版本同步被当作一等公民来设计——缺任何一条，拆分只是把同卡抢占换成了跨池悬挂。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-6\">六 · 当长 prompt 撞上短生成：一次 rollout 批次悬挂暴露的边界</h3>\n\n<p>先看一个不涉及具体数字的失败链条：RL 训练侧的 rollout 批次里混着数学题与代码补全两类采样。数学题 prompt 短、CoT 生成长；代码题 prompt 长（整段仓库上下文）、补全短。同卡部署时，长 prompt 的 chunked prefill 占满 SM 并持续抽取 HBM 带宽，正在解码的序列每步都要读 KV、写新 KV，TPOT 被拖长；而 prefill 又因 decode 的持续占用拿不到完整算力，TTFT 抬升。调度器为了守住 TTFT 把 prefill 切成更小 chunk，chunk 变小又让 decode 的抢占更频繁，两边同时劣化，形成典型的木桶效应——吞吐由最慢的那条约束决定，而不是由平均利用率决定。更糟的是，rollout 采样要求同一批次内所有请求返回后才能算 advantage，任何一个请求的 TTFT 超标都会让整个批次等待，训练步被拖住。这正是分离式预填/解码要解决的问题：把 prefill 与 decode 的资源争抢从物理上拆开。</p>\n\n<p>但它解决的问题有明确边界。分离式方案把 rollout 引擎拆成 prefill 池与 decode 池：prefill 池只做 chunked prefill 产出完整 prompt KV，经 NVLink 或 RDMA 把 KV 块传到 decode 池目标实例的 HBM，传输与块表注册原子完成；decode 池以 continuous batching 推进自回归，每步只写新 token 的 KV，结束后回传 token 序列与 logprob 并释放 KV 块。两池按队列深度与 SLO 独立伸缩，prefill 按 prompt token/s 扩容、decode 按并发序列数扩容，并行策略也各自匹配——prefill 偏 TP，decode 偏 EP/DP。它不解决的是同一 prompt 多采样之间的 KV 重复计算，那是前缀 KV 共享的范畴；也不解决权重版本一致性、采样分布正确性这类训练侧问题。把分离式当成万能加速手段，会在短 prompt 短生成的负载上直接亏本：拆分收益抵不过跨池传输与两套调度器的固定开销。</p>\n\n<p>代价首先落在端到端时延的加法项上：</p>\n\n<div class=\"formula\">$$T_{\\text{e2e}}=T_{\\text{prefill}}+T_{\\text{kv\\_transfer}}+T_{\\text{decode}}$$</div>\n\n<p>长 prompt 下 KV 体积可达数百 MB，跨池传输时延可能吃掉 prefill 并行化省下的全部时间，TTFT 反而劣化——这是该方案最典型的失效条件。互联带宽因此成为规模上限：NVLink 域内尚可，跨节点走 RDMA 时，KV 传输与 decode 池的 HBM 写入争抢带宽，长 prompt 比例一高，prefill 池扩得再大也喂不饱 decode 池。第二个代价是工程复杂度：两池之间要维护请求路由、KV 句柄与故障转移，传输失败或块表注册不一致会导致请求悬挂，rollout 批次无法收敛；rollout 引擎与训练侧的权重同步必须同时覆盖两池，同步窗口内版本不一致会带来采样分布偏差。可用下表判断是否落入适用区：</p>\n\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>拆分收益</th><th>主要风险</th></tr></thead><tbody><tr><td>短 prompt、长 CoT，TTFT/TPOT 需同时达标</td><td>高，消除同卡抢占</td><td>decode 池容量与 KV 驻留</td></tr><tr><td>长 prompt、短补全</td><td>中，prefill 可独立扩容</td><td>数百 MB KV 跨池传输吃掉 TTFT 收益</td></tr><tr><td>短 prompt、短生成</td><td>低，不足以抵消传输与两套调度开销</td><td>固定开销占比上升</td></tr></tbody></table>\n\n<p>工程判断应落在路由策略上：调度器按 prompt 长度分流，超过某个体量阈值的长 prompt 请求优先留在同池做 prefill 后原地解码，或只把 KV 传输放在 NVLink 域内完成，避免跨节点 RDMA 的长尾；同时以队列深度与 TTFT/TPOT 双 SLO 驱动两池伸缩，而不是用单一吞吐指标。分离式预填解码的适用边界由此清晰：它买的是 prefill 与 decode 各自匹配并行策略、独立扩缩容的自由度，付出的是 KV 跨池传输的带宽与两池状态一致性维护的成本；当传输项在 $T_{\\text{e2e}}$ 中占比超过 prefill 并行化节省的部分，这套拆分就不再是优化而是负债。</p>\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-7\">七 · 调度器入口：请求分类与路由决策</h3>\n<p>分离式 rollout 的第一步不在 GPU 上，而在调度器里。rollout 调度器收到一条采样请求时，手里只有 prompt token 序列、采样参数和该请求所属的训练步标签。它要做的第一个决策是：这条请求去 prefill 池的哪个实例。路由依据是 prompt 长度——短 prompt（代码补全类）与长 prompt（数学题长 CoT 类）在 chunked prefill 下的 chunk 数、SM 占用时长和 KV 产出体积完全不同，混在同一实例队列里会让长 prompt 把短 prompt 的 TTFT 拖长。工程上通常按 prompt token 数分桶，桶边界对齐 chunk 大小（例如按 chunk 的整数倍切分），保证同一实例队列内的请求在 prefill 阶段耗时方差可控。</p>\n<p>这一步的输入是请求元数据，输出是一个路由目标（prefill 实例 ID + 预留的 KV 块句柄占位）。代价不在算力，而在调度器自身的队列管理：路由表要同时感知两池的实时队列深度，否则会把请求压到已经饱和的 prefill 实例上。更关键的是，路由必须与 decode 池的容量联动——如果 decode 池没有可接纳的序列槽位，prefill 做完的 KV 无处可去，只能滞留在 prefill 实例的 HBM 里，反过来挤占 prefill 的批处理空间。因此路由决策实际上是一个两阶段约束满足：先看 decode 池的空闲并发序列数，再选 prefill 实例。这一步的延迟贡献是调度排队时间，在 SLO 里计入 TTFT 的前段。</p>\n<p>具体例子：一批 rollout 采样中同时混有 200 token 的代码补全请求和 8000 token 的数学题请求。调度器把前者路由到短 prompt 桶对应的 prefill 实例（chunk 数少、周转快），后者路由到长 prompt 桶实例并预留更大的 KV 块区间。若不做这层分类，8000 token 请求的 chunked prefill 会占满实例的 SM 数个时间片，短请求的 TTFT 被推到 SLO 之外。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-8\">八 · Prefill 实例：chunked prefill 与 KV 产出</h3>\n<p>prefill 实例收到请求后执行 chunked prefill：把 prompt 切成固定大小的 chunk，逐 chunk 前向，每 chunk 结束把该层的 K/V 写入为本实例分配的 KV 块。chunk 大小的选择直接决定这一步的两个代价维度：chunk 太小则 kernel 启动与块表更新开销占比升高，chunk 太大则单 chunk 占用 SM 时间过长、实例内其他请求的 TTFT 抖动变大。prefill 池偏 TP 并行，因为 prefill 是计算密集型、矩阵乘的宽度随 hidden dim 展开，TP 能把单层计算摊到多卡上，缩短单 chunk 的墙钟时间。</p>\n<p>这一步的输出是完整 prompt 的 KV 块集合，其体积可估算为：</p>\n<div class=\"formula\">$$V_{\\text{KV}} \\approx 2 \\times L_p \\times n_{\\text{layer}} \\times d_{\\text{head}} \\times n_{\\text{kv\\_head}} \\times b_{\\text{bytes}}$$</div>\n<p>其中因子 2 对应 K 与 V，$b_{\\text{bytes}}$ 是 KV 元素字节数。长 prompt 下这个体积可达数百 MB 量级——这正是跨池传输成为瓶颈的根源。prefill 实例在这一步的显存代价是双份的：既要容纳当前 chunk 的激活，又要容纳已产出但尚未传走的 KV 块。如果传输跟不上，KV 块在 prefill 实例 HBM 里堆积，prefill 池的有效批大小被压缩，吞吐下降。因此 prefill 实例的块分配策略必须与传输带宽匹配，产一块传一块，而不是攒满再传。</p>\n<p>具体例子：8000 token 的数学题 prompt，按 2048 token 一个 chunk 切四块。每个 chunk 前向完成后立即触发该 chunk 的 KV 块传输，prefill 实例只需同时持有当前 chunk 与在途 chunk 的 KV，显存占用被压到与 chunk 数无关的水平。若改为全部 prefill 完成后再整体传输，prefill 实例需持有全部数百 MB KV，同实例上其他请求的批处理空间被挤掉。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-9\">九 · KV 跨池传输：带宽账与原子注册</h3>\n<p>这是整个机制里唯一新增的、原同卡方案不存在的步骤。prefill 实例把 KV 块经 NVLink（同机架内）或 RDMA（跨节点）写入 decode 池目标实例的 HBM。传输与块表注册必须原子完成：decode 实例的块表要么完整指向一块已落地的 KV，要么完全不指向；中间态会导致 decode 步读到半块数据，生成出乱码 token，而这类错误在 rollout 里表现为采样分布偏移，污染训练信号。</p>\n<p>传输时延的量级由体积除以有效带宽决定。端到端时延分解为：</p>\n<div class=\"formula\">$$T_{\\text{e2e}} = T_{\\text{prefill}} + T_{\\text{kv\\_transfer}} + T_{\\text{decode}}$$</div>\n<p>工程判断的关键在于 $T_{\\text{kv\\_transfer}}$ 是否小于拆分带来的 prefill 加速。拆分消除了同卡抢占，$T_{\\text{prefill}}$ 下降；但如果 KV 体积大、互联带宽被其他流量（训练侧梯度同步、其他 rollout 批次的 KV）挤占，$T_{\\text{kv\\_transfer}}$ 可能吃掉全部收益，TTFT 反而劣化。这就是为什么长 prompt 场景下必须做传输与 prefill 的重叠：chunk 级流水，第 i 个 chunk 的 KV 在传的同时第 i+1 个 chunk 在算，把 $T_{\\text{kv\\_transfer}}$ 隐藏在 $T_{\\text{prefill}}$ 之内，只剩最后一个 chunk 的传输暴露在关键路径上。</p>\n<p>具体例子：四 chunk 的 8000 token prompt，若串行执行则总时延为四个 chunk 计算加四次传输之和；改为流水后，关键路径约为四个 chunk 计算加最后一次传输。传输带宽的代价还体现在 decode 池一侧：decode 实例的 HBM 写入带宽被 KV 落地占用，与自回归生成每步写新 token KV 的写入竞争，高并发下 decode 的 TPOT 会因 HBM 写带宽饱和而抬升。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-10\">十 · Decode 实例接管：continuous batching 与增量 KV</h3>\n<p>decode 实例收到 KV 落地信号与块表句柄后接管请求，把它插入 continuous batching 的活跃序列集合。此后每一步只做一件事：为当前 batch 内所有活跃序列生成下一个 token，并只为新 token 写一份 KV（一个 token 的 KV，体积是 prompt KV 的 $1/L_p$ 量级）。decode 池偏 EP/DP 并行，因为 decode 是访存密集型、每步计算量小、瓶颈在权重与 KV 的读取带宽，EP 把权重切分到多卡降低单卡权重读取压力，DP 则让不同副本承接不同序列、提高并发序列数。</p>\n<p>这一步的输入是已落地的 prompt KV 块表加当前 batch 的序列状态，输出是逐步生成的 token 与对应 logprob。代价集中在 HBM 带宽：每步要读全部活跃序列的 KV（随序列长度线性增长）加权重，写新 token KV。批大小受 KV 显存总量约束——decode 实例的并发序列数上限由 HBM 容量除以平均序列 KV 体积决定，这也是 decode 池按并发序列数而非 token/s 扩容的原因。continuous batching 的价值在于序列完成即释放槽位、新请求即插入，使这个上限被动态填满。</p>\n<p>具体例子：decode 实例同时承载若干条长短不一的序列，短补全请求几步就完成并释放 KV 块，空出的槽位立刻被新落地的长 CoT 请求填入。若按静态批组织，短请求完成后槽位空转到整批结束，decode 池的有效并发序列数下降，TPOT 达标但吞吐浪费。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-11\">十一 · 回传与释放：logprob 回流与块回收</h3>\n<p>序列生成到终止符或长度上限后，decode 实例把 token 序列与逐步 logprob 回传给 rollout 调度器。logprob 是 RL 采样的必需产物——重要性采样比、KL 惩罚都依赖它，因此回传不是可选的日志，而是训练侧的数据输入。回传体积与生成长度成正比，长 CoT 的 logprob 数组本身就有可观字节数，回传路径若与 KV 传输共用互联，会与下一批请求的 KV 传输争带宽。</p>\n<p>回传完成后 decode 实例释放该序列占用的 KV 块，块回到空闲池供后续请求使用。释放的时序必须与回传确认对齐：先确认调度器已收到完整序列再释放，否则传输失败时无法重放。这一步的失败模式是请求悬挂——若块表注册不一致或回传丢包，调度器侧该请求永远处于未完成状态，rollout 批次无法收敛，训练步被卡住。工程上需要超时加幂等重试，把悬挂请求重新路由到 prefill 池重做。</p>\n<p>具体例子：一条长 CoT 序列生成数百 token 后终止，logprob 数组回传调度器，decode 实例随即释放其 KV 块。若释放早于回传确认，回传失败时该序列的 KV 已被复用覆盖，只能整条重算，浪费的 prefill 算力远大于一次确认的延迟。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-12\">十二 · 两池独立伸缩：按不同指标扩容</h3>\n<p>最后一步是资源侧的闭环：prefill 池按 prompt token/s 扩容，decode 池按并发序列数扩容。两个指标不同源，因为两池的瓶颈不同——prefill 受算力约束，扩容单位是能吞下多少 prompt token；decode 受 KV 显存与 HBM 带宽约束，扩容单位是能同时承载多少活跃序列。rollout 中长短样本比例变化时（例如训练步从数学题主导切到代码题主导），两池的需求比例随之漂移，独立伸缩让资源跟着比例走，而不是整机重配。</p>\n<p>伸缩决策的输入是各自队列深度与 SLO 余量，输出是副本数调整。这里有一个耦合约束：prefill 池扩容过快会把 KV 灌进 decode 池，若 decode 池未同步扩容，KV 在 decode 侧堆积、块表耗尽，新请求无法落地，prefill 产出的 KV 反压回 prefill 实例。因此两池伸缩需要共享一个全局的 KV 块预算视图，prefill 的产出速率不得超过 decode 的落地与消费速率。这一步的代价是控制面的复杂度：两池各自伸缩意味着两套健康检查、两套故障转移、两套权重同步——rollout 引擎与训练侧的权重版本必须同时覆盖两池，同步窗口内两池版本不一致会让采样分布出现偏差，且这种偏差在 prefill 与 decode 之间不对称，难以用单侧指标察觉。</p>\n<p>具体例子：某训练步的采样配方从短 prompt 短补全切到长 prompt 长 CoT，prefill 池的 prompt token/s 需求上升、decode 池的并发序列数需求因单序列变长而下降。独立伸缩让 prefill 池扩副本、decode 池缩副本，整机资源重新配平；若两池绑定伸缩，则要么 prefill 不够、TTFT 超标，要么 decode 过配、HBM 浪费。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-13\">十三 · 拆分收益的边界：KV 搬运与两池一致性</h3>\n<p>端到端时延由三段构成：<div class=\"formula\">$$T_{\\text{e2e}}=T_{\\text{prefill}}+T_{\\text{kv\\_transfer}}+T_{\\text{decode}}$$</div>拆分把前两项从同一张卡的 SM 与 HBM 带宽争抢中解耦，却把第三项从零变成了显式成本。KV 体积随 prompt 长度线性增长，长 prompt 下可达数百 MB，跨池搬运要走 NVLink 或 RDMA，其时间与有效带宽成反比。判断拆分是否划算的工程判据是：prefill 池因不再被 decode 抢占而节省的时间，必须大于这段搬运时延；否则 TTFT 反而劣化。短 prompt 短生成的样本，KV 小、prefill 本来就快，节省量不足以抵消传输与块表注册的固定开销，这类负载应留在同卡路径上，而不是强行拆池。</p>\n<p>搬运本身不是一次纯拷贝。prefill 实例产出完整 prompt KV 后，需把 KV 块写入目标 decode 实例的 HBM，并同步完成块表注册；传输与注册必须原子完成，否则 decode 侧会看到“块已到但表未登记”或反向的悬挂状态。传输失败、注册不一致都会让请求卡在两池之间，rollout 批次迟迟不收敛。因此路由层要持有 KV 句柄并具备故障转移能力：句柄失效时能重投递到另一 decode 实例，而不是让采样请求无限等待。这条路径上的显存代价是双份的——prefill 侧在传完前不能释放源块，decode 侧已预留目标块，峰值占用高于单池方案。</p>\n<p>两池独立扩缩容的代价落在同步窗口上。prefill 池按 prompt token/s 扩容、decode 池按并发序列数扩容，各自的并行策略也不同（prefill 偏 TP，decode 偏 EP/DP），这意味着权重同步必须同时覆盖两套并行布局，转换本身要额外的时间与显存。同步窗口内若两池版本不一致，采样分布会出现偏差，对 RL rollout 而言这是比吞吐更严重的问题——偏差会污染训练信号。工程上应把版本一致性做成路由的前置条件：调度器只在两池报告同一权重版本时才放行新请求，把不一致窗口压缩到零，代价是同步期间吞吐短暂下降。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>长 prompt、KV 达数百 MB</td><td>搬运时延接近或超过 prefill 节省量</td><td>TTFT 劣化，互联带宽成为瓶颈</td></tr><tr><td>块表注册与传输不原子</td><td>请求长时间停留在中间态</td><td>批次不收敛，decode 侧显存被占死</td></tr><tr><td>两池权重版本漂移</td><td>同 prompt 采样分布不一致</td><td>训练信号偏差，需回滚重跑</td></tr></tbody></table>\n<p>规模上限因此不在算力，而在互联与路由复杂度：跨池带宽决定长 prompt 的可拆阈值，两池路由与故障转移的状态机决定系统能扩到多少副本而不失控。一个可操作的判断是——当 rollout 负载中长 prompt 占比高且 TTFT 是硬约束时，拆池收益明确；当样本以短 prompt 短补全为主时，搬运与一致性维护的开销会吃掉全部收益，此时应退回同卡分块预填路径。</p>\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-14\">十四 · Goodput 公式的分母：两池木桶效应的数学形态</h3>\n<p>先看那条被反复引用的目标式：</p>\n<div class=\"formula\">$$\\text{Goodput} = \\max\\ \\frac{N_{\\text{req}}}{\\max\\left(\\frac{\\sum L_p}{\\text{thr}_{\\text{prefill}}},\\ \\frac{\\sum L_o}{\\text{thr}_{\\text{decode}}}\\right)},\\quad \\text{s.t.}\\ \\text{TTFT}\\le S_{\\text{TTFT}},\\ \\text{TPOT}\\le S_{\\text{TPOT}}$$</div>\n<p>逐项拆。$N_{\\text{req}}$ 是调度窗口内被判定为“有效完成”的请求数——注意它不是提交数，而是 token 序列与 logprob 都已回传调度器、KV 块已释放的请求数，悬挂请求不计入分子。$\\sum L_p$ 是这批请求的 prompt token 总量，$\\sum L_o$ 是实际生成的 output token 总量（含被截断的样本按实际写出计）。$\\text{thr}_{\\text{prefill}}$ 与 $\\text{thr}_{\\text{decode}}$ 分别是两池在满足各自 SLO 前提下的可持续速率，单位分别是 prompt token/s 与 output token/s。</p>\n<p>分母取 max 而非求和，是这条式子最关键的一步推导。若两池串行依赖（一个请求必须先 prefill 完才能 decode），在稳态流水下，系统的请求完成速率由较慢的那一段决定：设 prefill 段每请求耗时 $1/\\text{thr}_{\\text{prefill}}$（按 token 摊），decode 段每请求耗时 $1/\\text{thr}_{\\text{decode}}$，则单请求端到端驻留时间近似为两段之和，而吞吐（单位时间完成请求数）在流水填满后等于瓶颈段速率。写成 token 口径即 $\\min(\\text{thr}_{\\text{prefill}},\\text{thr}_{\\text{decode}})$ 的倒数形式，等价于分母取 max。这就是“木桶效应”的严格表述：把 prefill 与 decode 拆到不同池，不会让分母变小，只会让两个 $\\text{thr}$ 各自摆脱对方的抢占而抬高——收益全部来自 $\\text{thr}$ 的提升，而非公式结构的变化。</p>\n<p>约束项不可省。$\\text{TTFT}\\le S_{\\text{TTFT}}$ 约束的是 prefill 段加 KV 传输段，$\\text{TPOT}\\le S_{\\text{TPOT}}$ 约束的是 decode 段每步间隔。这两个约束把“无限扩副本换吞吐”的路堵死：decode 池副本加太多，单实例并发序列数上升，TPOT 因 batch 内序列争抢而劣化；prefill 池 chunk 切得太细，TTFT 里的首 chunk 时延占比上升。工程含义是，Goodput 的优化必须在可行域内做，扩缩容是带约束的搜索而非单调加资源。</p>\n<p>具体例子：数学题短 prompt 长 CoT 的批次，$\\sum L_p$ 小、$\\sum L_o$ 大，分母由 decode 段主导，此时扩 prefill 池对 Goodput 几乎无贡献，应把资源压到 decode 池并按 EP/DP 扩并发序列；代码题长 prompt 短补全的批次则相反，分母由 prefill 段主导，扩 decode 池是浪费。这正是两池独立扩缩容的数学依据。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-15\">十五 · 端到端时延分解与 KV 传输项的推导</h3>\n<p>端到端时延的近似式是：</p>\n<div class=\"formula\">$$T_{\\text{e2e}}=T_{\\text{prefill}}+T_{\\text{kv\\_transfer}}+T_{\\text{decode}}$$</div>\n<p>三项各自的构成需要写清，否则无法落到可实现。$T_{\\text{prefill}}$ 在 chunked prefill 下不是单块时间，而是 $\\sum_{c=1}^{C} t_{\\text{chunk}}(c)$，其中 $C=\\lceil L_p / B_{\\text{chunk}}\\rceil$，$B_{\\text{chunk}}$ 是每 chunk 的 token 数；$t_{\\text{chunk}}$ 随 chunk 序号变化，因为注意力对已写入 KV 的读取量随位置增长，靠后的 chunk 单位 token 成本更高。$T_{\\text{decode}}$ 近似为 $L_o \\cdot \\text{TPOT}_{\\text{eff}}$，$\\text{TPOT}_{\\text{eff}}$ 是该请求在 continuous batching 中的实际每步间隔，受同批并发序列数影响。</p>\n<p>关键是中间项。KV 体积的推导：每 token 每层的 KV 字节数为 $2 \\cdot h_{\\text{kv}} \\cdot d_{\\text{head}} \\cdot b_{\\text{elem}}$（K 与 V 各一份，$h_{\\text{kv}}$ 为 KV 头数，$d_{\\text{head}}$ 为头维，$b_{\\text{elem}}$ 为元素字节数），乘层数 $n_{\\text{layer}}$ 与 token 数 $L_p$ 得</p>\n<div class=\"formula\">$$V_{\\text{kv}} = 2 \\cdot n_{\\text{layer}} \\cdot h_{\\text{kv}} \\cdot d_{\\text{head}} \\cdot b_{\\text{elem}} \\cdot L_p$$</div>\n<p>于是 $T_{\\text{kv\\_transfer}} \\approx V_{\\text{kv}} / \\text{BW}_{\\text{eff}} + t_{\\text{launch}}$，$\\text{BW}_{\\text{eff}}$ 是 NVLink 或 RDMA 路径上的有效带宽（扣除协议开销与并发争抢），$t_{\\text{launch}}$ 是传输发起与块表注册的固定开销。代入量级：长 prompt 下 $V_{\\text{kv}}$ 可达数百 MB，即便走 NVLink，这一项的绝对时延也不可忽略；若跨节点走 RDMA，有效带宽更低，该项会显著放大。</p>\n<p>推导的关键一步在这里：拆分带来的 prefill 收益是 $\\Delta T_{\\text{prefill}} = T_{\\text{prefill}}^{\\text{shared}} - T_{\\text{prefill}}^{\\text{dedicated}}$，即消除同卡抢占后 prefill 段的缩短量。拆分真正划算的条件是</p>\n<div class=\"formula\">$$\\Delta T_{\\text{prefill}} &gt; T_{\\text{kv\\_transfer}}$$</div>\n<p>否则端到端 TTFT 反而劣化——这正是失败模式里“传输时延吃掉 prefill 节省的时间”的形式化。工程判断：短 prompt 场景下 $\\Delta T_{\\text{prefill}}$ 本来就小（抢占损失有限），而 $V_{\\text{kv}}$ 虽小但 $t_{\\text{launch}}$ 固定开销占比高，不等式往往不成立，拆分收益不足以抵消传输开销。所以路由层需要按 $L_p$ 设阈值，低于阈值的请求走同池路径，这是伪代码里必须有的分支。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-16\">十六 · 路由与准入的伪代码：把公式变成判定</h3>\n<p>调度器侧的判定逻辑可以直接由上面两个式子导出。以下为可实现形态（伪代码，非 <code>&lt;pre&gt;</code> 排版，按行读）：</p>\n<ul>\n<li>输入：请求 $r$，含 $L_p$、预估 $L_o$（由历史分布或采样参数上限给出）、当前两池队列深度 $q_p, q_d$、两池实测 $\\text{thr}_{\\text{prefill}}, \\text{thr}_{\\text{decode}}$、互联有效带宽 $\\text{BW}_{\\text{eff}}$。</li>\n<li>第一步，估 $V_{\\text{kv}}(r)$ 与 $T_{\\text{kv\\_transfer}}(r) = V_{\\text{kv}}/\\text{BW}_{\\text{eff}} + t_{\\text{launch}}$。</li>\n<li>第二步，估 $\\Delta T_{\\text{prefill}}(r)$：用同池基线下的抢占系数 $\\alpha$（由当前同卡 prefill/decode 并发比测得）乘 $T_{\\text{prefill}}^{\\text{dedicated}}$ 得基线时延，差值即收益。</li>\n<li>第三步，若 $\\Delta T_{\\text{prefill}}(r) \\le T_{\\text{kv\\_transfer}}(r)$，标记 $r$ 为同池执行，跳过跨池路径。</li>\n<li>第四步，否则按 $L_p$ 选 prefill 实例：在满足 $q_p$ 未超阈值的实例中取 $\\arg\\min$ 预估完成时间；chunk 大小 $B_{\\text{chunk}}$ 按 $L_p$ 与当前实例负载反比调整，保证首 chunk 尽快产出以压 TTFT。</li>\n<li>第五步，prefill 完成后发起 KV 块传输，目标 decode 实例按 $\\arg\\min$ 预估 TPOT 劣化量选取（即当前并发序列数最接近但未超 SLO 上限者）。</li>\n<li>第六步，传输与块表注册原子完成：先写目标实例块表的预留项（状态 pending），传输完成回调里翻为 committed，失败则回滚并重路由；任何时刻块表状态与 HBM 实际内容一致，杜绝悬挂。</li>\n<li>第七步，decode 实例接管，continuous batching 推进，每步只写新 token KV；结束回调把 token 序列与 logprob 回传，释放 KV 块。</li>\n</ul>\n<p>代价落在两处。其一，第三步的判定依赖 $\\text{BW}_{\\text{eff}}$ 与 $\\alpha$ 的在线估计，估偏会导致误路由：把本该同池的短请求送进跨池路径，白付一次传输；把长请求留在同池，TTFT 超标。其二，第六步的原子性要求块表与传输通道共享同一事务语义，跨 NVLink 与 RDMA 两种路径要各写一套回滚逻辑，这是工程复杂度的主要来源。吞吐侧的代价是调度器每请求多做两次浮点估算与一次队列查询，相对 prefill 本身可忽略，但队列深度查询若走跨节点 RPC，会成为调度器自身的瓶颈，需本地缓存加周期刷新。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-17\">十七 · 两池扩缩容的速率匹配推导</h3>\n<p>扩缩容规则不能凭感觉，要由 Goodput 公式反解。设 prefill 池副本数为 $n_p$、decode 池副本数为 $n_d$，单副本可持续速率分别为 $s_p$（prompt token/s）与 $s_d$（output token/s），则 $\\text{thr}_{\\text{prefill}} = n_p s_p$、$\\text{thr}_{\\text{decode}} = n_d s_d$。使分母最小的资源配置满足两段速率相等：</p>\n<div class=\"formula\">$$\\frac{\\sum L_p}{n_p s_p} = \\frac{\\sum L_o}{n_d s_d} \\;\\Rightarrow\\; \\frac{n_p}{n_d} = \\frac{\\sum L_p}{\\sum L_o} \\cdot \\frac{s_d}{s_p}$$</div>\n<p>这就是“prefill 池按 prompt token/s 扩容、decode 池按并发序列数扩容”的定量版本。注意 $s_d$ 的单位是 output token/s，与 decode 池的并发序列数不是一回事：单副本 $s_d$ 随并发序列数先升后降（TPOT 约束下存在最优点），所以 decode 池扩容不是简单加副本，而是在副本数与单副本并发之间找 $s_d$ 的最大值点。工程上表现为 decode 池的扩容指标应是“队列深度对应的预估 TPOT 余量”，而非单纯序列计数。</p>\n<p>比例式的实际用途是给扩缩容一个前馈项。rollout 的批次配方在提交前已知（数学题与代码题的比例由采样配置决定），$\\sum L_p / \\sum L_o$ 可按批次预估，于是 $n_p/n_d$ 的目标比例可提前算出，不必等队列深度反馈。反馈项只做修正：当实测 $\\text{thr}$ 偏离预估，按偏差比例微调。前馈加反馈的结构避免了纯反馈在长短样本比例突变时的滞后——比例突变时，纯反馈要等队列积压才动作，期间 TTFT 或 TPOT 已经破 SLO。</p>\n<p>具体例子：一个批次里数学题占多数，$\\sum L_o$ 远大于 $\\sum L_p$，比例式给出 $n_p/n_d$ 远小于 1，decode 池应占多数副本；若沿用上一批次（代码题为主）的配比，prefill 池副本闲置而 decode 池排队，Goodput 被 decode 段卡住。反过来，代码题批次里 $n_p/n_d$ 应大于 1，且 prefill 池应偏 TP 并行以缩短单请求 prefill 时延，decode 池偏 EP/DP 以容纳更多并发序列——并行策略与副本比例是同一套推导的两个输出。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-18\">十八 · 权重同步窗口与两池版本一致性</h3>\n<p>rollout 引擎与训练侧的权重同步必须同时覆盖两池，这一条在公式里没有位置，但它决定采样分布是否可信。设同步窗口为 $[t_0, t_1]$，prefill 池在 $t_p$ 完成切换、decode 池在 $t_d$ 完成切换，若 $t_p \\ne t_d$，窗口内存在请求的 prompt KV 由旧版本算出、decode 由新版本推进，或反之。这种跨版本拼接的采样分布偏差无法用 Goodput 公式衡量，却直接污染 RL 的训练信号。</p>\n<p>可实现的约束是让同步成为两池的联合屏障：调度器在 $t_0$ 停止向两池派发新请求，等待两池在途请求排空（或达到预设的排空超时后强制丢弃并重路由），两池各自加载新权重并自检，全部就绪后统一在 $t_1$ 恢复派发。代价是同步窗口内两池算力空转，窗口长度由最长在途请求的剩余 decode 步数决定——长 CoT 样本会把窗口拉得很长。缓解手段是把同步做成滚动式：按层或按专家分片切换，配合请求级版本标签，使新请求只落在已切换的分片上，但这要求 KV 块带版本号并在跨池传输时校验，进一步加重块表事务的复杂度。</p>\n<p>工程判断：同步窗口的代价与批次配方相关。长 CoT 占比高的批次，在途请求剩余步数长，排空等待代价大，此时应倾向“短窗口加版本标签”的方案；短补全占比高的批次，排空快，联合屏障的简单方案更划算。这条判断与第三节的路由阈值、第四节的副本比例共用同一组输入（$L_p$、$L_o$ 分布），应在同一处配置里统一给出，而不是分散在三个模块各自拍板。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-19\">十九 · 拆分的失效边界：传输项如何吃掉收益</h3>\n<p>把端到端时延写成三项相加，是为了让边界条件显式暴露：<div class=\"formula\">$$T_{\\text{e2e}}=T_{\\text{prefill}}+T_{\\text{kv\\_transfer}}+T_{\\text{decode}}$$</div>拆分方案成立的前提是第三项足够小，使前两项因消除同卡抢占而获得的缩短不被抵消。KV体积随层数、头数与prompt长度线性增长，长prompt下可达数百MB量级；此时传输时延由互联带宽与两端HBM写入共同决定，而prefill池省下的时间来自不再与decode争抢SM与HBM带宽——两者量级相近时，TTFT反而劣化。因此路由决策不能只看prompt长度，必须把传输代价并入判据：仅当$T_{\\text{prefill}}^{\\text{拆}}+T_{\\text{kv\\_transfer}} &lt; T_{\\text{prefill}}^{\\text{合}}$时才值得跨池，否则请求应留在同卡路径上做chunked prefill。</p>\n<p>失效条件可归为三类。其一，短prompt短生成：KV小、prefill本就轻，拆分收益不足以抵消传输与两池路由开销，属于负收益区。其二，长prompt且互联带宽紧张：数百MB的KV块在NVLink或RDMA上排队，传输时延吃掉prefill节省的时间，TTFT超标。其三，一致性失败：传输与块表注册要求原子完成，一旦传输中断或块表注册不一致，decode池持有半份KV却已接管请求，请求悬挂，rollout批次无法收敛。此外，rollout引擎与训练侧的权重同步必须同时覆盖两池，同步窗口内版本不一致会直接污染采样分布。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>KV规模</th><th>拆分判据</th><th>主要代价</th></tr></thead><tbody><tr><td>短prompt短补全</td><td>小</td><td>不拆</td><td>传输与路由开销占优</td></tr><tr><td>短prompt长CoT</td><td>小</td><td>拆</td><td>decode池并发序列数扩容</td></tr><tr><td>长prompt短补全</td><td>数百MB</td><td>按带宽余量判定</td><td>传输时延可能吃掉prefill收益</td></tr></tbody></table>\n<p>落到可实现层面，调度器需要一个准入函数而非静态路由：输入为prompt token数、目标decode实例的可用HBM块、当前互联带宽余量，输出为跨池或同卡。伪代码思路是：<ul><li>估算KV字节数$S_{\\text{kv}}$与传输时延$T_{\\text{kv\\_transfer}}=S_{\\text{kv}}/B_{\\text{link}}$；</li><li>比较拆分与同卡的TTFT预测值，取小者；</li><li>跨池路径上先预留decode侧块表项，再发起传输，注册成功后才把请求句柄交给decode实例；</li><li>注册失败则回滚预留并重路由，避免悬挂。</li></ul>系统代价随之明确：互联带宽成为共享资源，prefill池按prompt token/s扩容、decode池按并发序列数扩容，两者扩缩容节奏不同步时，带宽争用会同时压低两池的有效吞吐。规模上限因此不由单池算力决定，而由互联带宽与两池路由、故障转移的复杂度共同约束。</p>\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-20\">二十 · 请求形态决定拆分是否有意义</h3>\n<p>分离式预填解码不是普适加速器，它的收益完全由请求的长度配方决定。设一条请求的prompt长度为$L_p$、生成长度为$L_o$，则prefill阶段的计算量正比于$L_p$、KV写入量正比于$L_p$，decode阶段的计算量正比于$L_o$但每步都要重读全部历史KV。两类负载对硬件的需求方向相反：prefill是计算密集、以矩阵乘为主、偏好大TP切分把单次前向摊薄；decode是访存密集、每步只产生一个token、偏好大EP/DP把并发序列数堆高以摊薄权重读取。当一条请求的$L_p$与$L_o$量级相当时，两阶段在同卡上交替执行，抢占的是同一批SM与同一份HBM带宽，木桶效应尚不尖锐；而当$L_p/L_o$严重失衡时，配方就分化为两个极端。</p>\n<p>数学推理类rollout是短prompt长CoT的典型：prompt可能只有几百token，但思维链展开到数千甚至上万token，decode阶段占据端到端时延的绝大部分。此时若prefill与decode同卡，短prompt的prefill虽然只占几十毫秒，却会在每个decode步之间插入抢占，把TPOT的抖动放大。代码补全类rollout则相反：仓库级上下文或长文件作为prompt可达数万token，生成只是几十到几百token的补全片段，prefill占绝对主导，decode几乎可以忽略。把这两类请求混在同一批里，调度器无论怎么排都会让一方等待另一方。</p>\n<p>关键在于，负载配方不是静态的。RL训练过程中采样温度、奖励信号、课程学习都会让长度分布漂移：早期策略生成的CoT短，训练推进后CoT逐渐变长，$L_o$的均值与方差同时上升。分离式架构的价值正在于这种漂移下仍能维持SLO——prefill池按prompt token/s扩容、decode池按并发序列数扩容，两池的伸缩曲线互不干扰。反之，若长度分布稳定且$L_p \\approx L_o$，拆分带来的KV跨池传输开销无法被抢占消除的收益覆盖。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-21\">二十一 · 批大小必须按池分别组织</h3>\n<p>合并部署时只有一个批大小参数，它被迫在两种最优之间折中。分离后，prefill池的批由chunked prefill的chunk尺寸与并发chunk数共同决定：每个chunk承载固定token数的prompt片段，批内chunk数受限于prefill实例的算力与KV暂存空间。decode池的批则是continuous batching下的活跃序列数，每步为所有活跃序列各生成一个token，批越大权重读取越被摊薄，但KV cache占用线性上升。</p>\n<p>两个批的组织逻辑不可互换。prefill池若按decode的序列数组织批，会因单条prompt过长而撑爆暂存；decode池若按prefill的token数组织批，会因序列长度参差导致padding浪费与KV碎片。更隐蔽的代价在扩缩容粒度上：prefill池的扩容单位是token/s，一个副本能消化的prompt吞吐由chunk并行度决定；decode池的扩容单位是并发序列数，一个副本能承载的序列数由HBM中KV块总量除以平均序列KV体积决定。当长度分布漂移时，两池的扩容需求按不同斜率增长，这正是分离式架构相对整机重配的优势所在。</p>\n<div class=\"formula\">$$\\text{Goodput} = \\max\\ \\frac{N_{\\text{req}}}{\\max\\left(\\frac{\\sum L_p}{\\text{thr}_{\\text{prefill}}},\\ \\frac{\\sum L_o}{\\text{thr}_{\\text{decode}}}\\right)},\\quad \\text{s.t.}\\ \\text{TTFT}\\le S_{\\text{TTFT}},\\ \\text{TPOT}\\le S_{\\text{TPOT}}$$</div>\n<p>该式说明吞吐由两阶段中较慢的一侧决定。若prefill池的$\\text{thr}_{\\text{prefill}}$足以在SLO内消化全部prompt，而decode池的$\\text{thr}_{\\text{decode}}$因并发序列数不足而成为瓶颈，则增加prefill副本毫无意义，只会让KV传输队列更长。工程判断是：先测出当前长度配方下两阶段的token/s与序列/s需求比，再决定扩容投向哪一池；盲目对称扩容是最常见的容量浪费。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-22\">二十二 · 负载配方错配时的三种劣化</h3>\n<p>第一种劣化是长prompt下的传输反噬。长prompt的KV体积可达数百MB，跨池传输经NVLink或RDMA搬运这份KV的时延，可能吃掉prefill池因专用化而节省的全部时间。端到端时延近似为$T_{\\text{e2e}}=T_{\\text{prefill}}+T_{\\text{kv\\_transfer}}+T_{\\text{decode}}$，当$T_{\\text{kv\\_transfer}}$与$T_{\\text{prefill}}$同量级时，TTFT不但没有改善反而劣化。这类请求的正确配方是让prefill与decode在同一池内背驮执行，而不是强行拆分——拆分只在$T_{\\text{kv\\_transfer}}$远小于抢占损失的窗口内成立。</p>\n<p>第二种劣化是短prompt短生成下的收益倒挂。当$L_p$与$L_o$都很小时，prefill与decode各自只占几毫秒，同卡抢占的损失本就有限，而跨池传输的固定开销（建链、块表注册、句柄传递）却是每条请求都要付的。此时拆分引入的额外互联带宽与路由开销超过收益，Goodput反而低于合并部署。配方判断的量化门槛是：单请求KV传输时延占端到端时延的比例超过抢占损失的等效比例时，拆分不成立。</p>\n<p>第三种劣化是两池负载比例失衡导致的空转。若rollout批次中长prompt请求突然增多，prefill池队列积压而decode池因拿不到KV而饥饿；反之短prompt长CoT批次会让prefill池空闲、decode池满载。分离式架构允许两池独立伸缩，但伸缩有延迟，队列深度在伸缩窗口内会持续累积。调度器若不做跨池的准入控制，就会出现一池打满、另一池SM闲置的功率与算力浪费。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-23\">二十三 · 路由与准入：配方在调度器里的落地</h3>\n<p>负载配方的工程落地在rollout调度器的路由策略上。调度器接收采样请求后按prompt长度路由到prefill池的某个实例，路由依据不只是长度，还包括该实例当前的chunk队列深度与KV暂存余量。伪代码思路是：对每条请求估算其KV体积$V_{\\text{kv}} \\propto L_p \\cdot d_{\\text{model}} \\cdot b_{\\text{bytes}}$，据此判断目标prefill实例的暂存能否容纳、目标decode实例的HBM余量能否接收，两者同时满足才准入；否则请求在调度器侧排队，而不是先做prefill再发现无处安放。</p>\n<p>准入控制还必须考虑两池的版本一致性。rollout引擎与训练侧的权重同步需同时覆盖prefill池与decode池，同步窗口内若两池版本不一致，prefill产出的KV与decode侧的权重不匹配，采样分布会出现偏差。因此同步期间调度器应暂停跨池路由或把请求导向同版本的池对，这是配方之外但与之耦合的稳定性约束。传输失败或块表注册不一致会导致请求悬挂，rollout批次无法收敛，调度器需要为每条跨池请求维护超时与重试句柄。</p>\n<p>代价体现在互联带宽上。KV跨池传输占用NVLink或RDMA带宽，而这条带宽同时被权重同步、梯度归约等训练侧流量共享。当rollout批次的长prompt比例上升时，KV传输流量与训练通信流量叠加，互联成为整机瓶颈。配方设计因此要把KV传输的带宽预算纳入容量规划，而不是只算两池各自的算力。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-24\">二十四 · 配方与并行策略的耦合</h3>\n<p>prefill池偏TP、decode池偏EP/DP，这一并行度选择本身就是负载配方的函数。prefill阶段单次前向处理整段prompt，TP切分能把大矩阵乘摊到多卡、降低单卡显存压力；decode阶段每步只处理一个token，TP切分带来的每步all-reduce通信开销相对计算量过大，而EP/DP能把并发序列分散到更多卡上、摊薄权重读取。若长度配方偏向长prompt短补全，prefill池应配置更高的TP度与更大的chunk并行；若偏向短prompt长CoT，decode池应配置更高的DP度以承载更多并发序列。</p>\n<p>两池并行度不一致带来一个隐性代价：KV从prefill池的TP布局传到decode池的DP布局时，需要做KV块的重排与再分片。若两池的并行度拓扑不对齐，传输不仅是搬运，还包含布局转换，进一步抬高$T_{\\text{kv\\_transfer}}$。配方设计应在两池并行度之间保留可整除的映射关系，使KV块能按块表直接注册到目标实例，避免运行时重排。</p>\n<p>规模上限由此确定：受互联带宽与两池路由/故障转移复杂度约束，分离式架构的副本数不能无限扩张。每增加一对池副本，就多一条需要维护的KV句柄链路与一套故障转移逻辑。当rollout集群规模上升时，路由表的复杂度与故障域数量同步增长，配方必须在收益与运维复杂度之间取平衡。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-25\">二十五 · 配方判断的工程准则</h3>\n<p>把上述约束收敛成可执行的判断：先测当前rollout批次的长度分布，算出$\\sum L_p/\\text{thr}_{\\text{prefill}}$与$\\sum L_o/\\text{thr}_{\\text{decode}}$的比值，比值接近1说明两阶段负载均衡、拆分收益最小；比值远离1说明木桶效应显著、拆分有明确收益。再估算长prompt的KV体积与跨池传输时延，若传输时延占端到端时延的比例超过抢占损失的等效比例，则该类请求应走同池背驮路径而非跨池路径。最后检查两池并行度拓扑是否可整除映射，不可整除则先对齐拓扑再谈扩容。</p>\n<p>配方不是一次性配置，而是随训练进程滚动的参数。RL rollout的长度分布随策略演化漂移，调度器应周期性重算两池的队列深度比与扩容斜率，把prefill池按prompt token/s、decode池按并发序列数的伸缩曲线作为运行时策略而非静态容量。当某一池的队列深度持续超过阈值而另一池空闲时，说明当前配方已偏离，需要调整路由权重或触发跨池重平衡，而不是等待整机重配。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-26\">二十六 · 负载配方与失效边界：什么时候拆池是赚的，什么时候是赔的</h3>\n<p>拆池的收益来自两池并行度与批组织方式的差异化：prefill 池按 chunked prefill 组织批、以 prompt token/s 为扩容信号，decode 池按 continuous batching 的并发序列数为扩容信号，SLO 也拆成 TTFT 与 TPOT 两条独立约束。这套配方只对一种负载成立——prompt 长度与生成长度分布都足够\"重\"且彼此错位：数学题短 prompt 长 CoT 让 decode 池成为长时占用方，代码题长 prompt 短补全让 prefill 池成为瞬时压力方。此时两池各自按最优并行度（prefill 偏 TP、decode 偏 EP/DP）伸缩，木桶效应被拆成两条独立的水管。反过来，短 prompt 短生成的采样请求下，单请求的 prefill 与 decode 都极短，拆池带来的路由、KV 句柄维护与跨池传输开销压过收益，收益不足以抵消传输开销，此时同卡分块预填搭载解码反而更省。</p>\n<p>失效的第一条路径是 KV 传输吃掉 prefill 节省的时间。端到端时延近似为</p>\n<div class=\"formula\">$$T_{\\text{e2e}}=T_{\\text{prefill}}+T_{\\text{kv\\_transfer}}+T_{\\text{decode}}$$</div>\n<p>长 prompt 下 KV 体积可达数百 MB，跨池传输经 NVLink 或 RDMA 完成，传输时延与 KV 体积、互联有效带宽成正比；当 prompt 长到让 $T_{\\text{kv\\_transfer}}$ 逼近甚至超过同卡方案中省下的抢占时间，TTFT 反而劣化。这是拆分方案的硬边界：规模上限受互联带宽约束，而不是受单卡算力约束。工程判断上应先估算单位请求的 KV 字节数与池间可用带宽，再决定长 prompt 是否仍走拆池路径，或对超长 prompt 保留同卡回退。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>拆池判断</th><th>主要代价项</th></tr></thead><tbody><tr><td>短 prompt 长 CoT</td><td>收益明确，decode 池独立扩容</td><td>KV 体积小，传输开销可忽略</td></tr><tr><td>长 prompt 短补全</td><td>需核算带宽，可能劣化 TTFT</td><td>数百 MB KV 跨池传输</td></tr><tr><td>短 prompt 短生成</td><td>不建议拆分</td><td>路由与句柄维护压过收益</td></tr></tbody></table>\n<p>第二条失效路径在控制面：两池间需维护请求路由、KV 句柄与故障转移，传输失败或块表注册不一致会导致请求悬挂——prefill 实例已产出 KV 但 decode 侧未完成原子注册，请求既不在 prefill 队列也不在 decode 批中，rollout 批次无法收敛。批大小按池分别组织意味着悬挂请求不会像同卡方案那样被下一轮调度自然带走，必须靠显式的句柄超时与重路由兜底。第三条在权重同步：rollout 引擎与训练侧的同步需同时覆盖两池，同步窗口内两池版本不一致会让采样分布出现偏差，这在 RL 里直接污染优势估计。因此负载配方的最后一条不是批大小，而是把两池的版本屏障与句柄生命周期做成同一个可观测状态机。</p>\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-27\">二十七 · 硬件档位：按池的瓶颈选卡，而不是按整机选卡</h3>\n<p>分离式部署的第一条配方原则是：prefill池与decode池的瓶颈根本不同，因此选卡逻辑必须分开。prefill池是计算密集型，chunked prefill阶段的大矩阵乘把SM的MMA吞吐吃满，HBM带宽主要服务于权重读取与中间激活写回；decode池是带宽与容量密集型，每步只处理一个token，MMA利用率低，但需要反复读取全部权重与整条KV cache，HBM带宽和容量是硬约束。把这两类负载塞进同一档硬件，必然有一侧被浪费。</p>\n<p>配方上，prefill池优先选SM密度高、单卡算力强的档位，因为它的扩容单位是prompt token/s；decode池优先选HBM容量大、带宽高的档位，因为它的扩容单位是并发序列数，而并发序列数直接由KV cache占用决定。在GB200/GB300 NVL72机柜内，两池共享NVLink 5域，prefill池可以按较高TP度切分以压低单请求prefill时延，decode池则按EP/DP切分以容纳更多并发序列。判断依据是一条简单的不等式：若某档位卡的HBM容量为$C$、每序列KV占用为$k$字节，则该卡可承载的并发序列上限为$\\lfloor C/k \\rfloor$，decode池的副本数下限由此反推，而不是由算力反推。</p>\n<p>代价体现在功耗与机柜功率密度上：prefill池高算力档位单卡功耗高但副本数少，decode池大容量档位单卡功耗相对低但副本数多，两池混合后机柜总功率分布与同构部署不同，配电机柜的功率预算需要按池分别核算，不能沿用整机均摊。一个具体例子：数学题rollout的prompt短、CoT长，decode池成为木桶；此时应把更多机柜功率分配给decode档位，prefill池缩到刚好覆盖prompt token/s即可，反之代码补全场景则相反。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-28\">二十八 · 并行拓扑：prefill偏TP，decode偏EP/DP，拓扑随池走</h3>\n<p>并行拓扑不是全局常量，而是每池独立的配置项。prefill池的并行目标是压低单请求的prefill时延，因为TTFT的分子里$T_{\\text{prefill}}$占大头；TP把单层矩阵乘切到多卡，直接缩短chunked prefill的每块计算时间，TP度越高单请求prefill越快，但跨卡all-reduce通信量随TP度上升。decode池的并行目标是最大化并发序列数并压低每步TPOT，EP/DP把不同序列或不同专家分到不同卡上，单卡只需维护自己那份KV与权重分片，序列数随卡数线性扩展，而每步的通信主要是token路由与少量集合通信。</p>\n<p>拓扑选择可以用一个伪代码思路表达：对prefill池，给定目标TTFT预算$S_{\\text{TTFT}}$与单块计算时间$t_{\\text{blk}}$，TP度$p$需满足$\\lceil L_p/B_{\\text{chunk}}\\rceil \\cdot t_{\\text{blk}}/p + T_{\\text{kv\\_transfer}} \\le S_{\\text{TTFT}}$，即在传输时延已定的前提下反推最小TP度；对decode池，给定目标TPOT预算$S_{\\text{TPOT}}$与单步权重读取时间$t_w$，DP度$d$需满足$t_w/d \\le S_{\\text{TPOT}}$且$d \\cdot \\lfloor C/k \\rfloor \\ge N_{\\text{seq}}$。两个不等式分别约束两池的拓扑，互不干扰，这正是分离式相对同构部署的结构性优势。</p>\n<p>系统代价在互联上：prefill池的TP all-reduce走NVLink域内，带宽压力集中在prefill计算期间；decode池的EP路由通信量小但频繁，且与KV跨池传输共享同一NVLink/RDMA链路。若两池拓扑跨出单机柜，prefill池的TP通信被迫走RDMA，all-reduce时延会显著抬高$T_{\\text{prefill}}$，因此配方上应把prefill池的TP组约束在单机柜NVLink域内，decode池的DP组可以跨机柜展开。具体例子：一个NVL72机柜内切出若干prefill实例（TP组不出柜）与若干decode实例（DP组可跨柜），KV传输走柜间RDMA，这样prefill的TP通信与KV传输在物理链路上分离，避免互相排队。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-29\">二十九 · 量化方案：两池分别定精度，KV传输格式单独定</h3>\n<p>量化配方要按池拆成三层决策：权重精度、激活精度、KV cache精度。prefill池的计算是大矩阵乘，对权重与激活的量化更敏感，因为量化误差在长prompt的累积计算中会被放大；decode池每步只做向量-矩阵乘，权重读取是带宽瓶颈，低精度权重直接换来带宽节省与TPOT下降，对激活量化的敏感度相对低。因此配方上prefill池倾向保留较高精度的权重与激活（如FP8权重配FP8激活，或关键层保留更高精度），decode池则可以把权重压到NVFP4以换取权重读取带宽减半，KV cache按块量化以压缩跨池传输体积。</p>\n<p>KV传输格式是分离式特有的第三层决策：KV块从prefill池传到decode池，传输体积直接进入$T_{\\text{kv\\_transfer}}$。若KV以FP8或NVFP4块量化后传输，长prompt下数百MB的KV体积可按比例压缩，传输时延随之下降；但decode池后续每步要读这份KV做注意力，量化KV会引入注意力分数误差，需要在decode侧做反量化或保留缩放因子。配方判断是：当$T_{\\text{kv\\_transfer}}$在$T_{\\text{e2e}}$中占比超过$T_{\\text{prefill}}$时，KV量化传输是必要项；否则优先保KV精度，因为decode侧反量化的算力开销会侵蚀TPOT余量。</p>\n<p>代价体现在数值稳定性与工程复杂度上：两池精度不一致意味着权重同步时要把同一份训练权重分别转成两种量化格式，同步窗口内两池版本不一致会导致采样分布偏差（这是本算法已知的失败模式之一）；KV量化的缩放因子必须与块表一起原子注册，否则decode侧读到未注册的缩放因子会算出错误注意力。具体例子：数学题rollout的decode池承载长CoT，TPOT是SLO瓶颈，此时decode权重压到NVFP4、KV按块量化传输，收益直接体现在TPOT；而代码补全场景prompt长、decode短，prefill池的激活精度不能降，否则长prompt的prefill计算结果偏差会污染整条KV。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-30\">三十 · KV策略：块粒度、传输原子性、容量回收三件事</h3>\n<p>KV策略在分离式部署里要回答三个问题：块多大、怎么传、什么时候回收。块粒度决定传输的并行度与块表管理的开销：块太小则块表项数暴涨、注册与查找开销上升；块太大则单次传输的粒度粗，长prompt的KV传输无法与prefill计算流水重叠。配方上块大小应与chunked prefill的chunk边界对齐，使每个chunk产出的KV块在计算完成时即可发起传输，形成“算一块、传一块”的流水，把$T_{\\text{kv\\_transfer}}$部分隐藏在$T_{\\text{prefill}}$之内。</p>\n<p>传输原子性是正确性底线：KV块写入decode池HBM与块表注册必须原子完成，否则decode实例可能在块表尚未登记时就开始注意力计算，读到未初始化或半写入的KV。实现上可用“先写数据、后置有效位”的顺序加完成队列，decode侧的调度器只在有效位就绪后才把该请求纳入continuous batching。容量回收则按decode实例的序列生命周期：请求生成结束回传token与logprob后，decode实例释放KV块并通知prefill池的块表注销，避免块表泄漏导致后续请求路由到已满实例。</p>\n<p>系统代价在带宽与显存两侧：KV跨池传输占用NVLink/RDMA带宽，长prompt下数百MB的KV体积意味着传输时间与prefill计算时间同量级，若块粒度与chunk不对齐，传输无法重叠就会直接叠加进TTFT；decode池的HBM被KV块占满后无法接纳新序列，容量回收不及时会让decode池的有效并发序列数低于$\\lfloor C/k \\rfloor$。具体例子：一个长prompt请求的KV达数百MB，按chunk对齐的块粒度传输时，前几块在prefill仍在计算后续chunk时已到达decode池，decode实例可提前做块表注册与预取，端到端TTFT只增加最后一块的传输时延，而非整份KV的传输时延。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-31\">三十一 · 调度参数：两池各自的队列阈值与伸缩触发条件</h3>\n<p>调度参数必须按池独立设定，因为两池的扩容单位不同。prefill池按prompt token/s扩容，触发条件是prefill队列的待处理token总量超过阈值，或观测到的$T_{\\text{prefill}}$逼近TTFT预算减去传输时延后的余量；decode池按并发序列数扩容，触发条件是活跃序列数逼近$\\lfloor C/k \\rfloor$，或观测到的TPOT逼近$S_{\\text{TPOT}}$。两池的伸缩不应联动，否则长短样本比例变化时会把资源错配到非瓶颈池。</p>\n<p>路由参数是分离式特有的调度项：rollout调度器按prompt长度路由到prefill实例，路由策略要兼顾负载均衡与KV传输距离——把请求路由到与目标decode实例同机柜或同NVLink域的prefill实例，可以压低$T_{\\text{kv\\_transfer}}$。批参数上，prefill池的chunk大小与批大小要匹配chunked prefill的流水深度，decode池的continuous batching并发序列数上限由KV容量而非算力决定，超过容量上限的序列应排队而非强行纳入，否则会触发KV换出到主机内存，TPOT剧烈劣化。</p>\n<p>代价在调度开销与故障转移上：两池各自伸缩意味着调度器要同时维护两套队列视图与两套健康检查，prefill实例故障时其已产出但未传完的KV块需要重新计算或从块表恢复，decode实例故障时其持有的序列KV需要迁移或重放，这些路径的复杂度直接决定rollout批次能否收敛。具体例子：数学题rollout高峰时decode池序列数触顶，调度器应扩容decode副本而非扩容prefill；若误扩prefill，新增的prefill容量只会把更多KV推给已满的decode池，请求在传输后排队，TTFT与TPOT同时劣化。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-32\">三十二 · 可复现的配置思路：从SLO反推，按池定档，用公式验收</h3>\n<p>把上述五项合成一条可复现的配置流程，顺序是：先定SLO，再定池，再定档位与拓扑，再定量化与KV策略，最后用公式验收。第一步给定$S_{\\text{TTFT}}$与$S_{\\text{TPOT}}$，并按负载配方估算prompt长度与生成长度的分布，得到$\\sum L_p$与$\\sum L_o$的量级；第二步用端到端时延公式$T_{\\text{e2e}}=T_{\\text{prefill}}+T_{\\text{kv\\_transfer}}+T_{\\text{decode}}$把SLO拆成三段预算，其中$T_{\\text{kv\\_transfer}}$按KV体积与互联带宽估算，长prompt下数百MB的KV体积必须显式计入；第三步按第一节的容量不等式定decode档位与副本数，按第二节的TTFT不等式定prefill的TP度。</p>\n<p>第四步定量化：decode权重按NVFP4、KV按块量化传输，prefill保留FP8激活，两池权重同步格式在部署时一次性生成并版本对齐；第五步定KV块粒度与chunk边界对齐，块表注册与传输原子化，回收路径与decode序列生命周期绑定；第六步定调度阈值，prefill按token/s、decode按序列数分别设伸缩触发点，路由优先同域。验收用Goodput公式：</p>\n<div class=\"formula\">$$\\text{Goodput} = \\max\\ \\frac{N_{\\text{req}}}{\\max\\left(\\frac{\\sum L_p}{\\text{thr}_{\\text{prefill}}},\\ \\frac{\\sum L_o}{\\text{thr}_{\\text{decode}}}\\right)},\\quad \\text{s.t.}\\ \\text{TTFT}\\le S_{\\text{TTFT}},\\ \\text{TPOT}\\le S_{\\text{TPOT}}$$</div>\n<p>验收时要看的是木桶项：若$\\sum L_p/\\text{thr}_{\\text{prefill}}$显著大于$\\sum L_o/\\text{thr}_{\\text{decode}}$，说明prefill池是瓶颈，应加prefill副本或提高TP度；反之则加decode副本或降decode权重量化精度。若两者接近但TTFT或TPOT仍不达标，问题不在容量而在$T_{\\text{kv\\_transfer}}$或调度排队，应检查KV块粒度是否与chunk对齐、路由是否跨域。这条流程的工程判断是：分离式部署的配置不是一次性静态表，而是随rollout负载分布漂移的两池独立调参问题，任何把两池绑在一起伸缩的配方都会在长短样本比例变化时失效。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-33\">三十三 · 拆池配方的失效边界：互联带宽预算与两池版本一致性</h3>\n<p>把prefill池与decode池的并行拓扑分开配置，收益的前提是KV跨池传输时延被压进端到端预算之内。用公式约束：<div class=\"formula\">$$T_{\\text{e2e}}=T_{\\text{prefill}}+T_{\\text{kv\\_transfer}}+T_{\\text{decode}}\\le S_{\\text{TTFT}}+L_o\\cdot S_{\\text{TPOT}}$$</div>长prompt下KV体积可达数百MB，若互联有效带宽为$B$，则$T_{\\text{kv\\_transfer}}\\approx V_{\\text{kv}}/B$，这一项与prefill池省下的抢占时间直接对冲。工程判断是：当$T_{\\text{kv\\_transfer}}$超过$T_{\\text{prefill}}$的节省量时，拆池反而使TTFT劣化——这正是短prompt短生成场景下拆分收益不足以抵消传输开销的定量表述。因此路由策略必须按prompt长度设阈值：低于阈值的请求留在同卡prefill-decode，超过阈值才进拆池路径。</p>\n<p>并行拓扑与量化方案要按池分别定档，不能整机一套。prefill池吃的是GEMM密集型chunked prefill，偏TP并行、权重切分到多卡以压低单请求prefill时延，量化上对权重与激活都取较激进方案以提升算力利用率；decode池吃的是低算术强度的自回归步进，偏EP/DP并行以容纳更多并发序列，量化上更关注KV cache的字节数而非权重——KV量化直接决定单卡可驻留序列数与跨池传输体积。两池独立扩缩容的触发信号也不同：prefill池按prompt token/s扩容，decode池按并发序列数扩容，混用同一指标会导致一池空转。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>KV传输时延吃掉prefill节省</td><td>TTFT分位劣化而prefill池利用率不高</td><td>互联带宽占用，端到端延迟反升</td></tr><tr><td>块表注册与传输非原子</td><td>请求悬挂、rollout批次不收敛</td><td>decode池KV块泄漏，显存碎片化</td></tr><tr><td>两池权重版本不一致</td><td>采样分布偏差、logprob异常</td><td>同步窗口内两池同时降速</td></tr></tbody></table>\n<p>最隐蔽的边界是权重同步窗口：rollout引擎与训练侧的权重更新必须同时覆盖prefill池与decode池，两池版本不一致时采样分布出现偏差，而这一偏差不会以延迟指标暴露，只会以训练信号污染的形式出现。工程上应把版本号写进KV句柄，decode池拒绝接管版本不匹配的KV块，宁可让请求重走prefill也不跨版本拼接。故障转移同理：传输失败或块表注册不一致导致的悬挂请求必须有超时回收路径，否则decode池的并发槽位被死请求占满，扩容再多副本也无法提升goodput。</p>\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-34\">三十四 · 互联带宽：KV 跨池传输的物理上限</h3>\n<p>分离式预填解码的吞吐上限，在规模上去以后往往不是被 SM 算力卡住，而是被两池之间的互联带宽卡住。原因很直接：prefill 池产出的 KV 体积与 prompt token 数成正比，而 decode 池每接收一个请求就要把这整块 KV 搬进自己的 HBM。长 prompt 场景下，单个请求的 KV 体积可达数百 MB；当并发请求数上升，跨池传输的瞬时带宽需求就是「KV 体积 × 请求到达率」的乘积。这个乘积一旦逼近 NVLink 或 RDMA 链路的可用带宽，传输队列就开始堆积，$T_{\\text{kv\\_transfer}}$ 从微秒级膨胀到毫秒级，直接吃掉 prefill 池并行化省下来的时间。</p>\n<p>把这件事写成可核算的形式：设单请求 KV 体积为 $V_{\\text{kv}}$（字节），请求到达率为 $\\lambda$（req/s），则跨池带宽需求为</p>\n<div class=\"formula\">$$B_{\\text{cross}} = \\lambda \\cdot V_{\\text{kv}} \\cdot \\alpha$$</div>\n<p>其中 $\\alpha$ 是传输协议开销系数（块表元数据、对齐填充、重传余量）。工程判断的落点在于：$B_{\\text{cross}}$ 必须显著小于链路单向可用带宽，否则传输时延不再是固定开销而是排队时延，随负载非线性增长。NVLink 提供的是机内高带宽通道，RDMA 提供的是跨节点通道，两者带宽档位不同，决定了分离式部署的拓扑边界——prefill 池与 decode 池能否跨节点放置，取决于 $B_{\\text{cross}}$ 是否落在 RDMA 链路的舒适区内。一个具体例子：数学题 rollout 的 prompt 短但 CoT 极长，KV 体积小、传输压力低，拆分收益主要来自 decode 池的连续批处理效率；代码题 rollout 的 prompt 长、补全短，KV 体积大，传输成为主要成本项，此时若把两池放在同一 NVLink 域内，传输时延可控，若跨节点走 RDMA，则必须限制单批 prompt token 总量以压住 $B_{\\text{cross}}$。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-35\">三十五 · 显存与块表：decode 池的容量墙</h3>\n<p>decode 池的显存占用结构与 prefill 池完全不同。prefill 池在 chunked prefill 完成后即可释放中间激活，KV 块被传走，显存占用是「瞬时高峰型」；decode 池则要长期持有每个活跃序列的全部 KV，直到生成结束。因此 decode 池的显存墙由并发序列数与平均序列长度共同决定：并发序列数受 continuous batching 的批大小约束，而每条序列的 KV 随生成步数单调增长。规模上去以后，decode 池先崩的地方通常是 KV 块池耗尽——新请求的 KV 传进来了，但目标实例没有空闲块可注册，传输与块表注册的原子性被打破，请求悬挂。</p>\n<p>块表注册的原子完成是这条链路上最脆弱的一环。传输动作与块表写入必须作为一个不可分割的操作：若传输成功而块表注册失败，KV 数据在 HBM 里但没有归属，形成泄漏；若块表注册成功而传输中途失败，decode 实例会读到半截 KV，采样分布直接错乱。工程上常见的做法是预分配目标块、传输完成后以一次原子提交切换块状态，失败则回滚并释放预分配块。代价是 decode 池必须保留一定比例的预留块作为传输缓冲，这部分显存不参与有效批处理，等效于降低了 decode 池的可用并发容量。一个具体例子：当 rollout 批次中长短样本比例突变（短 prompt 长 CoT 的样本涌入），decode 池的序列长度期望值上升，KV 增长速率加快，预留块被快速消耗，块池耗尽先于 SM 利用率饱和出现——这就是 decode 池的容量墙，扩容 decode 副本比调批大小更有效。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-36\">三十六 · 功耗与并行策略的耦合</h3>\n<p>两池独立扩缩容的收益之一，是让 prefill 池与 decode 池各自跑在匹配的并行策略上：prefill 偏 TP，decode 偏 EP/DP。这个选择不只是性能问题，也是功耗问题。TP 并行在 prefill 阶段把单层计算切到多卡，SM 占用率高、HBM 带宽打满，单卡功耗处于高位但持续时间短；decode 阶段每步只处理一个 token，计算密度低、访存为主，EP/DP 并行下多副本分摊序列，单卡功耗处于中低位但持续时间长。若两池混跑在同一批 GPU 上，功耗曲线是两者的叠加，峰值功耗由 prefill 决定，而平均功耗被 decode 拉低，电源与散热按峰值配置，利用率却按平均值计——这是同卡抢占在功耗维度的隐性代价。</p>\n<p>拆分后，prefill 池可以按峰值功耗配置电源与散热，decode 池按持续功耗配置，两池的功耗预算独立核算。规模上去以后，功耗先崩的位置往往在 prefill 池的扩容瞬间：新副本拉起时权重加载与 warmup 带来瞬时功耗尖峰，若机架电源余量按稳态配置，尖峰会触发降频，chunked prefill 的吞吐随之下降，$T_{\\text{prefill}}$ 拉长，TTFT 超标。工程判断是给 prefill 池的扩缩容留出功耗斜坡，避免一次性拉起过多副本。一个具体例子：GB200 NVL72 机架内 prefill 池与 decode 池共享机架电源，prefill 池扩容时的功耗尖峰与 decode 池的稳态负载叠加，若不加斜坡控制，整机架进入功耗封顶状态，两池同时降频，分离式部署的 SLO 隔离优势被抵消。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-37\">三十七 · 尾延迟：木桶效应的真实形状</h3>\n<p>分离式部署把 TTFT 与 TPOT 拆给两个池分别负责，但端到端尾延迟不是两个池尾延迟的简单相加。端到端时延近似为</p>\n<div class=\"formula\">$$T_{\\text{e2e}} = T_{\\text{prefill}} + T_{\\text{kv\\_transfer}} + T_{\\text{decode}}$$</div>\n<p>三项中任何一项的尾部事件都会传导到端到端。prefill 池的尾延迟来自长 prompt 的 chunked prefill 排队——当队列深度超过副本处理能力，长 prompt 请求的 TTFT 尾部被拉长；传输的尾延迟来自链路拥塞与重传；decode 池的尾延迟来自批内长序列拖尾——continuous batching 中一条超长 CoT 序列会让整批的 TPOT 被它拖住。规模上去以后，最先崩的尾延迟项取决于负载配方：短 prompt 长 CoT 的负载，decode 池的拖尾是主因；长 prompt 短补全的负载，prefill 池排队与传输拥塞是主因。</p>\n<p>Goodput 的核算必须带 SLO 约束，否则吞吐数字没有意义：</p>\n<div class=\"formula\">$$\\text{Goodput} = \\max\\ \\frac{N_{\\text{req}}}{\\max\\left(\\frac{\\sum L_p}{\\text{thr}_{\\text{prefill}}},\\ \\frac{\\sum L_o}{\\text{thr}_{\\text{decode}}}\\right)},\\quad \\text{s.t.}\\ \\text{TTFT}\\le S_{\\text{TTFT}},\\ \\text{TPOT}\\le S_{\\text{TPOT}}$$</div>\n<p>这个式子的结构说明木桶效应：有效吞吐由两池中较慢的那个决定，而 SLO 约束把「较慢」的定义从纯吞吐扩展到尾延迟。一个具体例子：当 prefill 池按 prompt token/s 扩容、decode 池按并发序列数扩容时，若负载中长 prompt 比例上升，prefill 池的 $\\sum L_p/\\text{thr}_{\\text{prefill}}$ 项变大成为瓶颈，此时扩容 decode 池对 Goodput 无贡献，反而增加跨池传输的接收端压力。工程判断是先识别当前负载下哪一项是木桶短板，再决定扩哪个池，而不是两池等比扩容。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-38\">三十八 · 规模上去以后哪里先崩：故障转移与版本一致性</h3>\n<p>规模化的第二个崩溃点不在性能，而在一致性。两池间需维护请求路由、KV 句柄与故障转移：请求在 prefill 池完成、KV 已传到 decode 池、decode 池正在生成时，若 decode 实例故障，KV 句柄失效，请求必须重新路由回 prefill 池重算——重算的代价是整段 prompt 的 prefill 时间，尾延迟直接爆表。规模越大，单实例故障概率越高，重算请求占比上升，prefill 池的有效吞吐被故障重算挤占，形成正反馈式的容量衰减。</p>\n<p>更隐蔽的是权重同步窗口。rollout 引擎与训练侧的权重同步需同时覆盖 prefill 池与 decode 池，同步窗口内两池版本不一致会导致采样分布偏差：prefill 池用新权重算出 KV，decode 池用旧权重继续生成，KV 与 decode 权重的语义不匹配，logprob 失真。这个偏差不会表现为报错，而是表现为 rollout 批次无法收敛——采样分布偏移让策略梯度的方差变大，训练侧看到的是 reward 曲线抖动。工程上常见的处理是把权重同步做成两池的联合屏障：同步期间两池都停止接收新请求，已在进行中的请求要么等同步完成要么被 drain 掉，代价是同步窗口内的吞吐归零。同步频率越高，这个归零窗口占总时间的比例越大，规模上去以后这是不可忽略的吞吐税。一个具体例子：当 rollout 批次规模扩大、单批采样耗时拉长，权重同步的频率被迫降低以摊薄同步开销，但同步窗口变长又让版本不一致的暴露面变大，两池的路由层必须记录每个请求的权重版本号并在跨池传递时校验，版本不匹配则拒绝接管——这把一致性问题从「静默偏差」转成「显式失败」，代价是失败请求的重算开销。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-39\">三十九 · 互联带宽与尾延迟：拆分方案先崩在哪里</h3>\n<p>拆分方案把同卡抢占换成了跨池搬运，代价立刻从 SM 争用转移到互联链路上。端到端时延可近似写成 <span class=\"formula\">$$T_{\\text{e2e}}=T_{\\text{prefill}}+T_{\\text{kv\\_transfer}}+T_{\\text{decode}}$$</span>，其中 $T_{\\text{kv\\_transfer}}$ 由 KV 体积除以有效互联带宽决定。长 prompt 下 KV 体积可达数百 MB，若按每层每 token 的 KV 字节数估算，传输时间与 prompt token 数近似成正比，而 prefill 计算时间也随 token 数增长——两者赛跑的结果是：当互联带宽不足以让传输时间落在 prefill 时间的阴影里，拆分带来的 TTFT 收益就被吃掉，甚至因为排队与握手开销反而劣化。这是规模上去以后第一个崩点：不是算力不够，是链路先饱和。NVLink 域内的 prefill 池与 decode 池尚可承受，一旦跨节点走 RDMA，数百 MB 的 KV 块在拥塞时延抖动下会把 TTFT 的尾部分布拉长，SLO 约束 $\\text{TTFT}\\le S_{\\text{TTFT}}$ 先在高分位请求上失守。</p>\n<p>第二个崩点是两池扩缩容的相位差。prefill 池按 prompt token/s 扩容、decode 池按并发序列数扩容，两个控制器各自看自己的队列深度，天然存在滞后：数学题流量涌入时 prefill 池迅速加副本，产出的 KV 却堆在 decode 池入口等待接管，decode 池因长 CoT 占用序列槽位而扩容缓慢，结果 KV 块在传输缓冲里滞留，等效于把显存压力从单卡转移到了跨池队列。可用小表刻画这种失衡的代价结构：</p>\n<table class=\"mini\"><thead><tr><th>资源维度</th><th>拆分后的主要压力点</th><th>失效表现</th></tr></thead><tbody><tr><td>互联带宽</td><td>长 prompt 的数百 MB KV 搬运</td><td>TTFT 尾部劣化，传输吃掉 prefill 收益</td></tr><tr><td>显存</td><td>decode 池 KV 块驻留 + 传输缓冲</td><td>序列槽位不足，continuous batching 并发下降</td></tr><tr><td>路由与状态</td><td>KV 句柄、块表注册、故障转移</td><td>注册不一致导致请求悬挂，批次无法收敛</td></tr><tr><td>权重同步</td><td>两池版本一致性窗口</td><td>窗口内采样分布偏差，rollout 数据污染</td></tr></tbody></table>\n<p>第三层是稳定性与正确性的耦合代价。传输与块表注册要求原子完成，一旦传输失败或注册状态不一致，请求就悬挂在 decode 池的等待队列里，rollout 批次因个别样本不返回而无法收敛——这在 RL 训练里不是性能问题而是正确性问题，因为批次必须齐备才能算优势。更隐蔽的是权重同步：rollout 引擎与训练侧的权重更新需同时覆盖 prefill 池与 decode 池，同步窗口内两池版本不一致时，同一批次里前半段由旧权重 prefill、后半段由新权重 decode，采样分布出现系统性偏差。工程判断因此很直接：拆分方案适用于 prompt 与生成长度分布差异极大、且 TTFT 与 TPOT 需同时达标的场景；短 prompt 短生成的负载下，传输开销压过抢占收益，拆分不划算。规模上限由互联带宽与两池路由/故障转移复杂度共同封顶，扩容时应先看 KV 传输的有效带宽利用率，再看 decode 池的序列槽位周转，而不是先加 GPU。</p>\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-40\">四十 · 精度漂移：两池版本不一致与数值路径分叉</h3>\n<p>分离式架构把一次采样拆成两段执行，精度风险随之从“单卡单版本”变成“两池两版本”。prefill 池产出的 KV 与 decode 池消费的 KV 必须来自同一份权重、同一套量化尺度。若权重同步只覆盖了 prefill 池而 decode 池仍在旧版本上，prompt KV 由新权重编码、自回归由旧权重推进，采样分布立刻偏离训练侧策略。这种偏差不会报错，只会表现为 rollout 的 logprob 与训练侧重算值系统性错位，KL 项被污染，批次收敛变慢。诊断手段是把每条请求的 prompt token 数、prefill 池版本号、decode 池版本号、回传 logprob 的均值与方差绑成一个 trace 标签，按版本组合分组统计 logprob 偏差；偏差集中在某一版本组合上，就锁定为同步窗口问题。数值路径分叉是第二种形态：prefill 池偏 TP、decode 池偏 EP/DP，两池的归约顺序与累加次序不同，FP8/NVFP4 的缩放因子若在池间各自维护，同一段 KV 的数值语义就不一致。工程判断是让量化尺度随 KV 句柄一起传递，而不是各池独立推导。代价上，精度问题不直接吃延迟，但它让 goodput 的有效分子变小——被判定为无效的采样要重跑，等于把 prefill 池的 token/s 白烧一遍。</p>\n<div class=\"formula\">$$\\text{Goodput} = \\max\\ \\frac{N_{\\text{req}}}{\\max\\left(\\frac{\\sum L_p}{\\text{thr}_{\\text{prefill}}},\\ \\frac{\\sum L_o}{\\text{thr}_{\\text{decode}}}\\right)},\\quad \\text{s.t.}\\ \\text{TTFT}\\le S_{\\text{TTFT}},\\ \\text{TPOT}\\le S_{\\text{TPOT}}$$</div>\n<p>公式里 $N_{\\text{req}}$ 若混入了精度不合格的请求，分母不变而分子虚高，容量规划就会系统性低估所需副本数。举例：数学题短 prompt 长 CoT 的样本，CoT 段全部在 decode 池生成，一旦 decode 池版本落后，长 CoT 的每一步都在放大偏差，而短 prompt 的 prefill 段看起来完全正常——这类失败只在长生成样本上暴露，短补全样本把它掩盖掉。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-41\">四十一 · OOM 的三条来路与块表对账</h3>\n<p>decode 池的显存压力来自三个方向，必须分开归因。其一是 KV 块泄漏：请求结束时应释放 KV 块，但跨池场景下块的归属权在 prefill 池与 decode 池之间转移，若块表注册与传输不是原子完成，prefill 侧已释放而 decode 侧未登记，或反之，块就成为孤儿。其二是长 prompt 的瞬时峰值：数百 MB 的 KV 在传输落地瞬间占用 decode 实例 HBM，若该实例同时在跑高并发 continuous batching，新块写入与在途生成争抢同一片显存。其三是批抖动引发的预留过量：调度器为应对队列深度波动提前预留块，预留策略保守时显存利用率被压低，激进时直接 OOM。诊断靠块表对账：周期性比对 prefill 池导出的“已发出块”集合与 decode 池的“已注册块”集合，差集持续增长即为泄漏；差集为负则是重复注册，会在释放时二次回收同一块，属于更危险的静默损坏。工程上把块表做成带世代号的句柄，传输失败时按世代号回滚而不是按地址回滚，避免 ABA 问题。代价是每次对账要扫全量块表，频率过高会挤占调度器 CPU；实践上按 decode 实例粒度做增量对账，只核对最近一个窗口内变更的块。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-42\">四十二 · 批抖动与路由不均：队列深度是唯一可信信号</h3>\n<p>两池独立扩缩容的前提是各自队列深度可观测且可归因。批抖动的典型形态是 prefill 池按 prompt token/s 扩容、decode 池按并发序列数扩容，两个指标的时间常数不同：prefill 池的扩容响应快，decode 池的序列生命周期长、扩容滞后，于是短 prompt 长 CoT 的负载涌来时，prefill 池迅速消化完 prompt 却把压力全部倾泻到 decode 池，decode 池队列堆积、TPOT 劣化，而 prefill 池已经空闲。这不是容量不足，是两池扩容节奏错配。路由不均是另一形态：调度器按 prompt 长度路由，长度分桶的边界若与实例的实际负载不匹配，短 prompt 全部压到少数几个 prefill 实例，长 prompt 又集中到另一批，池内负载方差远大于池间。诊断要同时看池间队列深度比与池内实例队列深度的基尼系数；前者失衡说明扩缩容策略错配，后者偏高说明路由哈希或分桶设计有偏。修法是让路由键包含实例当前队列深度而非仅按长度分桶，并在 decode 池引入按剩余生成长度的准入控制，避免长 CoT 序列把短补全序列挤出批。代价是路由决策从无状态变成有状态，调度器需要维护实例负载视图，视图陈旧会导致误路由，因此视图刷新周期必须短于 decode 单步时延量级。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-43\">四十三 · 尾延迟尖刺：KV 传输与块表注册的原子性缺口</h3>\n<p>端到端时延近似 $T_{\\text{e2e}}=T_{\\text{prefill}}+T_{\\text{kv\\_transfer}}+T_{\\text{decode}}$，尾延迟尖刺几乎总是落在 $T_{\\text{kv\\_transfer}}$ 这一项上。长 prompt 的 KV 体积达数百 MB，经 NVLink 或 RDMA 传输时，若与同链路上的其他流量（权重同步、其他请求的 KV 搬运）竞争，单次传输时延的方差被放大。更隐蔽的是原子性缺口：传输完成与块表注册若分两步做，中间窗口内 decode 实例已收到数据但块表未登记，调度器认为请求未就绪而重复派发，或 decode 实例开始生成时读到未注册的块。表现为个别请求 TTFT 出现数量级跳变，而中位数完全正常——这正是尾延迟尖刺的特征，均值监控看不见它。诊断必须用分位数而非均值：对 $T_{\\text{kv\\_transfer}}$ 单独打点，按 prompt 长度分桶看 p99 与 p999，若长 prompt 桶的 p999 显著高于 p99，说明传输路径存在排队而非带宽不足；若各桶 p999 同步抬升，则是链路级拥塞。回滚策略上，传输超时的请求不应原地重试，而应退回 prefill 池重新分块预填并换一个 decode 实例目标，避免在同一链路上反复撞墙。代价是重试会二次消耗 prefill 算力，因此超时阈值要按 KV 体积设定而非全局统一。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-44\">四十四 · 监控面与回滚：把两池当一条链路来观测</h3>\n<p>监控的最小集合是四个维度：每请求 trace（prompt 长度、两池版本号、KV 体积、$T_{\\text{prefill}}$、$T_{\\text{kv\\_transfer}}$、$T_{\\text{decode}}$、回传 logprob 统计量）、每池队列深度与副本数、块表差集、链路带宽占用。关键设计是把 prefill 池与 decode 池的指标用同一个请求 ID 串起来，否则两池各自健康而端到端劣化的情形无法定位。回滚要分三层：请求级回滚——传输失败或块表不一致的请求退回重派，不污染批次；实例级回滚——某 decode 实例块表差集超阈值即摘除并重建，在途请求迁移到同池其他实例；版本级回滚——权重同步窗口内检测到两池版本不一致，暂停新请求准入，等两池对齐后再放行，已发出的请求按版本标签重算 logprob 校验。版本级回滚的代价是同步窗口内 goodput 归零，因此同步应做成滚动式：先更新 prefill 池的一个副本子集，验证 logprob 偏差在容差内再推进 decode 池，把窗口切成小段而非一次性冻结。判断准则很直接：当尾延迟尖刺与块表差集同时抬升，优先查原子性缺口；当 logprob 偏差按版本组合聚集，优先查同步窗口；当池内队列深度基尼系数走高而池间比正常，优先查路由分桶。这三条判据把失败模式从“rollout 不收敛”这种笼统现象，收敛到可回滚的具体机制上。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-45\">四十五 · 跨池边界的失效面：从 KV 句柄悬挂到版本漂移</h3>\n<p>分离式预填/解码的收益全部押在一条假设上：KV 跨池传输的代价小于同卡抢占省下的时间。这条假设在长 prompt 上最先崩。端到端时延可写成 <span class=\"formula\">$$T_{\\text{e2e}}=T_{\\text{prefill}}+T_{\\text{kv\\_transfer}}+T_{\\text{decode}}$$</span>，当 prompt 极长时 KV 体积可达数百 MB，<span class=\"formula\">$$T_{\\text{kv\\_transfer}}$$</span> 随 KV 字节数与互联有效带宽线性上升，prefill 池省下的那部分时间被传输整段吃掉，TTFT 反而比同卡方案更差。诊断上不能只看 TTFT 均值，要在调度器侧按 prompt 长度分桶记录 <span class=\"formula\">$$T_{\\text{kv\\_transfer}}/T_{\\text{prefill}}$$</span> 的比值：该比值越过 1 的桶就是拆分失效区，应把这类请求回退到同卡 prefill+decode 路径，或强制走更短的分块与更激进的量化以压缩 KV 字节数。传输与块表注册被设计成原子完成，恰恰说明非原子窗口是真实风险：注册成功而传输未达、或传输完成而块表未落，都会让 decode 实例持有一个指向空块的句柄，请求既不报错也不推进，rollout 批次永远等不到该样本的 token 序列与 logprob，整批无法收敛。监控必须把“已注册未就绪”的 KV 句柄数做成独立指标并设超时回收，而不是依赖请求级超时兜底。</p>\n<p>第二类失效来自两池独立扩缩容的相位差。prefill 池按 prompt token/s 扩容、decode 池按并发序列数扩容，两个信号的时间常数不同：数学题短 prompt 长 CoT 的负载会让 decode 池先被并发序列打满，而 prefill 池仍在低位；代码题长 prompt 短补全则相反。若扩缩容只看各自队列深度，会出现一池过载、另一池空转，端到端吞吐被木桶效应锁死，且 TPOT 尖刺表现为“decode 池排队等 KV 到达”与“KV 已到但 decode 无空闲槽位”两种形态交替出现。诊断要把 decode 侧每步的等待拆成 KV 等待与槽位等待两段计时，分别对齐到 prefill 池的产出速率与 decode 池的批组织策略；尾延迟尖刺若集中在 KV 等待段，说明路由把长 prompt 集中打到了少数 prefill 实例，应按 prompt 长度做一致性哈希而非简单轮询，避免单实例 chunked prefill 队列被长样本垄断。</p>\n<p>第三类是精度与版本漂移，也是最难在单请求维度看见的。rollout 引擎与训练侧的权重同步需同时覆盖 prefill 池与 decode 池，同步窗口内两池版本不一致时，prefill 用旧权重算出的 KV 被新权重的 decode 实例消费，采样分布出现系统性偏差，表现为 logprob 分布与训练侧参考值的 KL 缓慢抬升、而非报错。这类问题不会触发 OOM 或超时，只能靠两池各自上报权重版本号并在路由层拒绝跨版本 KV 传输来拦截；同时把 prefill 池与 decode 池的数值精度配置（如 KV 缓存量化档位）纳入同一份版本清单，任何一侧单独变更都视为不兼容。回滚策略因此不能是整机重启：按池粒度保留上一版权重与精度配置的快照，路由层维护“版本→池副本集合”的映射，发现 KL 抬升或句柄悬挂率越限时只把新请求切到旧版本副本，已在途请求让其自然结束，避免回滚本身制造第二批悬挂请求。OOM 则多由 decode 池 KV 块碎片化与 prefill 池 chunk 过大共同触发，监控应把两池的 HBM 高水位与块表碎片率并列，回滚动作优先缩 decode 并发序列上限而非降 prefill chunk，因为后者会直接拉长 TTFT 并放大传输占比。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>回滚/缓解动作</th></tr></thead><tbody><tr><td>长 prompt 传输吃掉收益</td><td>按长度分桶的传输/prefill 时延比</td><td>该桶回退同卡路径或压缩 KV</td></tr><tr><td>KV 句柄悬挂</td><td>已注册未就绪句柄数、批次不收敛</td><td>超时回收句柄，重路由该请求</td></tr><tr><td>两池扩缩容相位差</td><td>KV 等待与槽位等待分段计时</td><td>按长度一致性哈希、联动扩容阈值</td></tr><tr><td>权重/精度版本漂移</td><td>logprob KL 抬升、跨版本传输计数</td><td>按池切旧版本副本，拒绝跨版本 KV</td></tr></tbody></table>\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-46\">四十六 · 对照轴：拆分粒度与争抢消除方式</h3>\n<p>把本算法放进同族条目里看，第一根对照轴不是“是否分离”，而是“把哪一段工作从同一张卡上挪走”。分块预填搭载解码把prefill切成chunk，与decode在同一实例内交替发射，靠时间片错峰缓解SM争抢，KV始终留在本地HBM；预填解码分离Rollout把两阶段放到不同池，靠空间隔离彻底消除争抢，代价是KV必须跨池搬运；分页KV批量Rollout与KV中心分离式池化则把KV的存放位置作为一等公民，前者解决块级碎片与批量组织，后者把KV抽成可被多实例寻址的中心池。四者的争抢消除强度依次为：时间片错峰 < 空间隔离 < KV池化解耦。判断标准很直接——当TTFT与TPOT的SLO同时收紧、且prompt长度分布的方差大到无法用统一chunk尺寸抹平时，时间片错峰会让两边的尾延迟互相传染，此时只有空间隔离能给出可分别证明的达标路径。</p>\n<p>第二根轴是KV搬动量。本算法的跨池传输量与prompt token数成正比，单请求KV体积在长prompt下可达数百MB；分块预填搭载解码的搬动量恒为零；KV中心池化把搬动量从“每请求一次”变成“按块按需拉取”，在共享前缀多的负载下摊薄明显。于是选型可以写成一个不等式：设单请求KV体积为$V_{\\text{kv}}$、互联有效带宽为$B_{\\text{link}}$、同卡争抢导致的TTFT劣化量为$\\Delta_{\\text{contend}}$，则</p>\n<div class=\"formula\">$$\\text{分离收益} \\approx \\Delta_{\\text{contend}} - \\frac{V_{\\text{kv}}}{B_{\\text{link}}} - T_{\\text{route}}$$</div>\n<p>只有右端为正才值得拆池。短prompt短生成的rollout里$V_{\\text{kv}}$小但$\\Delta_{\\text{contend}}$同样小，右端趋近于零甚至为负，这正是适用边界里“拆分收益不足以抵消传输开销”的定量表达。工程上不要凭直觉拆，先把这三个量在目标机型上各测一次。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-47\">四十七 · 决策表：五类负载的落点</h3>\n<p>下表按负载形态给出首选与备选，列中“争抢主因”指当前瓶颈究竟来自SM占用还是HBM带宽，两者的处置手段不同：SM争抢靠并行度与时间片，带宽争抢只能靠物理隔离或压缩。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>争抢主因</th><th>首选</th><th>备选</th><th>否决条件</th></tr></thead><tbody>\n<tr><td>短prompt长CoT（数学题）</td><td>decode长期占用SM，prefill被饿死</td><td>本算法（分离池）</td><td>分块预填搭载解码</td><td>互联带宽不足，KV传输时延超过prefill节省</td></tr>\n<tr><td>长prompt短补全（代码）</td><td>prefill突发挤占decode带宽</td><td>分块预填搭载解码</td><td>本算法</td><td>prompt方差极大，chunk尺寸无法统一</td></tr>\n<tr><td>多采样共享同一prompt</td><td>重复计算而非争抢</td><td>Rollout前缀KV共享</td><td>KV中心池化</td><td>前缀命中率低</td></tr>\n<tr><td>多轮Agent、上下文反复增长</td><td>KV块碎片与寻址</td><td>分页KV批量Rollout</td><td>KV中心分离式池化</td><td>序列长度稳定、无碎片</td></tr>\n<tr><td>异构Agent协同、多模型接力</td><td>跨实例KV交接</td><td>KV中心分离式池化</td><td>本算法</td><td>模型间KV布局不兼容</td></tr>\n</tbody></table>\n<p>读表的方式是自上而下排除：先看争抢是否真实存在（若瓶颈是重复计算，直接跳到前缀共享类），再看KV搬动量是否被互联吃掉，最后看两池路由与故障转移的运维成本是否被团队消化。第三列与第四列的差别在于是否需要改动实例内的调度器：首选方案通常要动调度逻辑，备选方案多数只动部署拓扑。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-48\">四十八 · 与投机、量化、批不变条目的组合关系</h3>\n<p>本算法与特征级投机采样Rollout是正交的：投机在decode池内部用草稿模型提高每步产出token数，分离则决定decode池的物理边界。二者叠加时要注意，投机带来的接受率波动会改变decode池的有效并发序列数，进而改变按并发序列数扩容的伸缩信号——扩容指标应从“在飞序列数”改为“每步有效token产出率”，否则草稿被大量拒绝时decode池会误判为负载不足而缩容。与NVFP4量化Rollout稳定化叠加时，量化压缩的是权重与激活，KV跨池传输的体积并不因权重NVFP4而减小，除非KV本身也以低精度存放；因此“量化省下的带宽”不能计入分离收益的分子，这是常见的估算错误。</p>\n<p>与批不变Rollout采样叠加时有一个隐性冲突：批不变要求同一请求在不同批组合下产出相同采样结果，而分离池意味着请求先在prefill池成形、再到decode池排队，两池的批组成天然不同。若采样实现依赖批内随机数流的排布，跨池重组会破坏不变性。处置办法是把随机数流绑定到请求ID而非批槽位，让批不变性由请求级种子保证，而不是由批级排布保证。这一步不做，分离带来的调度自由度会直接转化为采样分布偏差，与权重同步窗口内两池版本不一致导致的偏差叠加，收敛问题会变得难以归因。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-49\">四十九 · 与异步Rollout流水线的边界</h3>\n<p>异步Rollout流水线关心的是“生成与训练重叠”，本算法关心的是“生成内部两阶段不互抢”。二者可以串联：异步流水线把rollout批次切成若干在飞批次，每个批次内部再走分离池。串联后的代价是资源核算变成二维——既要在时间上错开训练与推理的显存峰值，又要在空间上给prefill池与decode池分别留出余量。一个可操作的判据是看权重同步窗口：若同步窗口内两池必须同时停机换权重，则异步流水线的重叠收益被抵消；若能做到prefill池先换、decode池后换且窗口内不接受新请求，则分离池反而给了流水线一个天然的换版屏障。反过来，若团队尚未解决两池的故障转移，异步流水线会把悬挂请求放大成整批不收敛，此时应先做单池的请求级超时与重试，再谈分离。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-50\">五十 · 适用条件的量化门槛与工程判断</h3>\n<p>把适用条件写成可测门槛，比写成定性描述更有用。三条门槛：其一，prompt长度的分位数比（如P99与P50之比）足够大，使得统一chunk尺寸下prefill池的尾延迟无法满足TTFT；其二，单请求KV体积与互联带宽之比小于同卡争抢造成的TTFT劣化量，即第一节的不等式为正；其三，decode池的并发序列数在目标SLO下足以让continuous batching填满SM，否则拆出去的decode池会因批太小而丧失效率，分离反而降低整体goodput。第三条常被忽略：分离把decode池的批组成从“混合长短请求”变成“纯decode请求”，批内token产出更均匀，但也失去了prefill填充空档的机会，小规模部署时decode池的SM利用率会明显低于混跑。</p>\n<p>goodput的核算必须带双边SLO约束，这正是本算法与单一吞吐指标算法的分野：</p>\n<div class=\"formula\">$$\\text{Goodput} = \\max\\ \\frac{N_{\\text{req}}}{\\max\\left(\\frac{\\sum L_p}{\\text{thr}_{\\text{prefill}}},\\ \\frac{\\sum L_o}{\\text{thr}_{\\text{decode}}}\\right)},\\quad \\text{s.t.}\\ \\text{TTFT}\\le S_{\\text{TTFT}},\\ \\text{TPOT}\\le S_{\\text{TPOT}}$$</div>\n<p>式中分母取两池耗时的较大者，木桶效应被显式写进公式：任一池扩容不足，goodput不涨。工程判断落在最后一步——当两池的扩容信号分别来自prompt token/s与并发序列数时，两个信号的时间常数不同，prefill池对突发prompt敏感、decode池对长尾生成敏感，若共用一套伸缩控制器会互相干扰。可行做法是给两池各自独立的队列深度阈值与冷却窗口，并在路由层保留一个小的溢出通道：当prefill池队列超过阈值时，允许少量请求回落到混跑实例，用可控的争抢换取不排队。这个溢出通道的存在，恰恰说明分离不是全有或全无的开关，而是按队列深度动态调节的隔离度。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-51\">五十一 · 拆与不拆之间：同族算法怎么选，以及本方案的失效边界</h3>\n<p>本方案不是孤立存在的：它与分块预填搭载解码、Rollout 前缀 KV 共享属于同一族“rollout 加速”手段，但三者解决的瓶颈各不相同。分块预填搭载解码解决的是同卡上 prefill 抢占 decode 的调度问题，靠 chunk 化把长 prompt 切成小片插进 decode 步之间，资源仍在同一批 GPU 上；前缀 KV 共享解决的是同一 prompt 多次采样间的重复计算，靠复用前缀 KV 降低总 prefill 量；而本方案解决的是资源争抢本身——把 prefill 与 decode 拆到不同池、各自使用匹配的并行策略（prefill 偏 TP、decode 偏 EP/DP），从而消除同卡抢占。选择时先问三个问题：瓶颈是 TTFT 还是 TPOT？样本间是否存在可复用的长前缀？互联带宽是否足以承载 KV 搬运？三者答案不同，选型就不同。</p>\n<p>决策表可按负载形态与 SLO 约束来组织。短 prompt 短生成场景下，两池拆分带来的收益不足以抵消 KV 传输与路由开销，分块预填搭载解码更划算；长 prompt 短补全（代码题）场景下，prefill 是主要成本，拆分后 prefill 池可独立按 prompt token/s 扩容，收益明显；短 prompt 长 CoT（数学题）场景下，decode 是主要成本，decode 池按并发序列数扩容、prefill 池保持小规模即可；同一 prompt 多采样（如 best-of-n）场景下，前缀 KV 共享的收益远大于池拆分，应优先做共享，再考虑拆分。若 TTFT 与 TPOT 需同时达标，且分布差异极大，本方案是唯一能同时满足两条 SLO 的结构。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>首选</th><th>理由</th></tr></thead><tbody><tr><td>短 prompt 短生成</td><td>分块预填搭载解码</td><td>拆分收益不足以抵消传输开销</td></tr><tr><td>长 prompt 短补全</td><td>本方案（prefill 池扩容）</td><td>prefill 独立扩容，TTFT 可控</td></tr><tr><td>短 prompt 长 CoT</td><td>本方案（decode 池扩容）</td><td>decode 并发序列数决定吞吐</td></tr><tr><td>同 prompt 多采样</td><td>前缀 KV 共享优先</td><td>复用前缀 KV，降低总 prefill 量</td></tr></tbody></table>\n<p>失效条件集中在传输与一致性两条线上。端到端时延近似为</p>\n<div class=\"formula\">$$T_{\\text{e2e}}=T_{\\text{prefill}}+T_{\\text{kv\\_transfer}}+T_{\\text{decode}}$$</div>\n<p>长 prompt 下 KV 体积可达数百 MB，跨池传输时延可能吃掉 prefill 节省的时间，端到端 TTFT 反而劣化——此时拆分是负收益。互联带宽成为规模上限：NVLink 域内尚可，跨节点走 RDMA 时带宽与尾延迟都会放大传输成本。另一条线是两池间需同时维护请求路由、KV 句柄与故障转移，传输失败或块表注册不一致会导致请求悬挂，rollout 批次无法收敛；rollout 引擎与训练侧的权重同步需同时覆盖 prefill 池与 decode 池，同步窗口内两池版本不一致会导致采样分布偏差。工程判断是：先量化 KV 传输时延占端到端时延的比例，若该比例接近 prefill 节省量，就退回同卡分块方案；只有当 decode 侧并发序列数足够大、prefill 侧 prompt 长度分布足够长尾时，池拆分的收益才稳定为正。</p>\n\n<h3 id=\"alg-disagg-prefill-decode-rollout-sec-52\">五十二 · 同族算法怎么选：拆分收益的边界与失效条件</h3>\n<p>本方案与分块预填搭载解码、Rollout前缀KV共享构成同一决策面，但三者优化的瓶颈不同：分块预填解决单卡内prefill与decode的时隙交错，前缀KV共享解决同一prompt多采样间的重复计算，本方案解决的是两池资源争抢与并行策略错配。选择时先看负载的prompt长度与生成长度分布是否同时发散——若分布集中（如短prompt短生成），拆分带来的KV跨池传输开销无法被并行度收益抵消，端到端时延近似式 <span class=\"formula\">$$T_{\\text{e2e}}=T_{\\text{prefill}}+T_{\\text{kv\\_transfer}}+T_{\\text{decode}}$$</span> 中的传输项直接成为TTFT的劣化源；此时应退回单池分块预填。若分布发散且TTFT与TPOT需同时达标，拆分才进入候选。</p>\n<p>第二个判据是KV体积与互联带宽的比值。长prompt下KV体积可达数百MB，跨池传输时延可能吃掉prefill节省的时间，端到端TTFT反而劣化——这是本方案最典型的失效模式。工程上应先用 <span class=\"formula\">$$\\text{Goodput} = \\max\\ \\frac{N_{\\text{req}}}{\\max\\left(\\frac{\\sum L_p}{\\text{thr}_{\\text{prefill}}},\\ \\frac{\\sum L_o}{\\text{thr}_{\\text{decode}}}\\right)},\\quad \\text{s.t.}\\ \\text{TTFT}\\le S_{\\text{TTFT}},\\ \\text{TPOT}\\le S_{\\text{TPOT}}$$</span> 估算两池木桶位置，再判断传输项是否落在SLO余量内；若余量不足，宁可牺牲并行度匹配也不拆分。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>选本方案</th><th>选相邻方案</th></tr></thead><tbody><tr><td>prompt/生成长度分布</td><td>双发散，长短样本比例波动大</td><td>集中，或仅prompt侧发散</td></tr><tr><td>KV体积 vs 互联带宽</td><td>传输时延在TTFT余量内</td><td>数百MB量级吃掉余量</td></tr><tr><td>并行策略需求</td><td>prefill偏TP、decode偏EP/DP</td><td>单池可统一并行度</td></tr><tr><td>运维复杂度</td><td>可维护两池路由与故障转移</td><td>无法承担跨池句柄一致性</td></tr></tbody></table>\n<p>第三个判据是运维与一致性代价。两池间请求路由、KV句柄与故障转移需同时维护，传输失败或块表注册不一致会导致请求悬挂，rollout批次无法收敛；rollout引擎与训练侧的权重同步需同时覆盖prefill池与decode池，同步窗口内两池版本不一致会导致采样分布偏差。若团队尚不具备跨池原子注册与版本对齐能力，应优先用前缀KV共享压低重复计算，再逐步引入拆分。规模上限受互联带宽与两池路由复杂度约束，NVLink与RDMA的档位选择直接决定拆分能否在长prompt场景成立。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2024 · Rollout引擎与训练解耦</td></tr><tr><td>解决什么</td><td>RL rollout的prompt长度与生成长度分布差异极大（数学题短prompt长CoT、代码题长prompt短补全…</td></tr><tr><td>一句话机制</td><td>把rollout引擎拆成prefill池与decode池，prefill池只做prompt的chunked prefi…</td></tr><tr><td>代价与失效</td><td>KV跨池传输引入额外互联带宽开销，长prompt下KV体积可达数百MB，传输时延可能吃掉prefill节省的时间；两池间需维护请求路由、K…</td></tr><tr><td>后继</td><td>批不变Rollout采样</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-disagg-prefill-decode-rollout · 共 8 个片段</p>\n";break;}}})();
